window.QUIZ_DATA = {"title":"2026年10月自考 13180 操作系统 · 押题练习","meta":{"prefix":"os","code":"13180","name":"操作系统","examMonth":"2026年10月","title":"13180 操作系统 · 押题练习","pageTitle":"2026年10月自考 13180 操作系统 · 押题练习","storageKey":"os13180.v1","flags":{"explain":true},"paper":{"target":100,"scores":{"single":1,"blank":2,"essay":5}},"mindmap":{"enabled":true,"file":"操作系统考点串讲-思维导图.md","label":"🗺 考点思维导图（串讲 8 章全览）"}},"chapters":["第一章操作系统概论","第二章操作系统运行环境与运行机制","第三章进程","第四章进程","第五章存储管理","第六章文件系统","第七章设备管理","第八章进程同步机制与死锁"],"questions":[{"id":1,"chapter":"第一章操作系统概论","type":"single","stem":"以下选项中，不属于操作系统的任务的是（ ）","ref":"操作系统组织和管理计算机系统中的硬件及软件资源，通过接口向用户提供各种服务功能。选项A不属于操作系统的任务","explanation":"操作系统组织和管理计算机系统中的硬件及软件资源，通过接口向用户提供各种服务功能。选项A不属于操作系统的任务。","options":[{"key":"A","text":"控制进程运行时候的各种状态转换"},{"key":"B","text":"组织和管理计算机系统中的硬件资源"},{"key":"C","text":"组织和管理计算机系统中的软件资源"},{"key":"D","text":"向用户提供各种服务功能"}],"answer":"A","explain":"操作系统组织和管理计算机系统中的硬件及软件资源，通过接口向用户提供各种服务功能。选项A不属于操作系统的任务。"},{"id":2,"chapter":"第一章操作系统概论","type":"single","stem":"在计算机系统中同时存在若干个运行着的程序，从宏观上看，这些程序在同时向前推进。这体现了操作系统的哪一特征（ ）","ref":"充分理解操作系统的三个特征","explanation":"充分理解操作系统的三个特征。","options":[{"key":"A","text":"共享性"},{"key":"B","text":"随机性"},{"key":"C","text":"并发性"},{"key":"D","text":"精确性"}],"answer":"C","explain":"充分理解操作系统的三个特征。"},{"id":3,"chapter":"第一章操作系统概论","type":"single","stem":"存储管理的任务是管理计算机（ ）","ref":"存储管理计算机内存的资源","explanation":"存储管理计算机内存的资源","options":[{"key":"A","text":"文件资源"},{"key":"B","text":"目录资源"},{"key":"C","text":"设备资源"},{"key":"D","text":"内存的资源"}],"answer":"D","explain":"存储管理计算机内存的资源"},{"id":4,"chapter":"第一章操作系统概论","type":"blank","stem":"______是一组控制和管理计算机硬件和软件资源，合理地对各类作业进行调度，以及方便用户使用的程序的集合","ref":"操作系统","explanation":"操作系统","blankCount":1,"blanks":[["操作系统"]],"explain":"考点1.1（第一章第一节）：**操作系统**是计算机系统中的系统软件，是一些程序模块的集合——有效地组织和管理计算机系统中的硬件及软件资源，合理地组织计算机工作流程，控制程序的执行，并向用户提供各种服务功能，使整个计算机系统高效运行。按“**管理资源**、**组织流程**、**控制执行**、**服务用户**”四个动词记忆。"},{"id":5,"chapter":"第一章操作系统概论","type":"blank","stem":"计算机系统的资源包括两大类：______和______。","ref":"硬件资源和软件资源","explanation":"硬件资源和软件资源","blankCount":2,"blanks":[["硬件资源"],["软件资源"]],"unordered":true,"explain":"考点1.1/2.1：计算机系统的资源分**硬件资源**与**软件资源**两大类，这也正对应操作系统的两大管理对象（组织和管理硬件及**软件资源**）。"},{"id":6,"chapter":"第一章操作系统概论","type":"essay","stem":"简述操作系统的特性。","ref":"1、并发：在计算机系统中同时存在多个程序，宏观上：这些程序是同时在执行的，微观上：任何时刻只有一个程序在执行，即微观上这些程序在CPU上轮流执行。2、共享：操作系统与多个用户的程序共同使用计算机系统中的资源。3、虚拟性：虚拟性是一种管理技术，该技术把物理上的一个实体变成逻辑上的多个对应物，或把物理上的多个实体变成逻辑上的一个对应物4、异步性：操作系统必须随时对以不可预测的次序发生的事件进行响应","explanation":"1、并发：在计算机系统中同时存在多个程序，宏观上：这些程序是同时在执行的，微观上：任何时刻只有一个程序在执行，即微观上这些程序在CPU上轮流执行。2、共享：操作系统与多个用户的程序共同使用计算机系统中的资源。3、虚拟性：虚拟性是一种管理技术，该技术把物理上的一个实体变成逻辑上的多个对应物，或把物理上的多个实体变成逻辑上的一个对应物4、异步性：操作系统必须随时对以不可预测的次序发生的事件进行响应。","points":["并发：宏观上同时在执行，微观上轮流执行","共享：操作系统与多个用户的程序，共同使用系统中的资源","虚拟：物理上的一个实体变成逻辑上的多个对应物","异步：随时对不可预测次序发生的事件进行响应"],"pointsMd":["并发：宏观上**同时**在执行，微观上**轮流**执行","共享：操作系统与多个用户的程序，**共同使用**系统中的资源","虚拟：物理上的一个实体变成逻辑上的**多个对应物**","异步：随时对**不可预测**次序发生的事件进行响应"],"explain":"考点1.1（第一章第一节）操作系统四大特征：（1）并发性——同时存在若干个运行着的程序，宏观上同时向前推进，微观上任何时刻只有一个在执行（在CPU上轮流执行）；（2）共享性——操作系统程序与多个用户程序共用系统中的各种资源，有互斥共享和同时共享两种形式；（3）虚拟性——一种管理技术，把物理上的一个实体变成逻辑上的多个对应物，或反之；（4）异步性——进程的执行不是一贯到底，而是走走停停，以不可预知的速度向前推进。口诀“并、共、虚、异”，**并发与共享**是两大支柱。"},{"id":7,"chapter":"第一章操作系统概论","type":"essay","stem":"简述操作系统的主要功能。","ref":"处理机管理功能：进程控制；进程同步；进程通信；调度； 2、存储器管理功能：内存分配；内存保护；地址映射；内存扩充； 3、设备管理功能：缓冲管理；设备分配；设备处理； 4、文件管理功能：文件存储空间的管理；目录管理；文件的读写管理和保护； 5、用户接口：命令接口；程序接口；图形接口","explanation":"处理机管理功能：进程控制；进程同步；进程通信；调度； 2、存储器管理功能：内存分配；内存保护；地址映射；内存扩充； 3、设备管理功能：缓冲管理；设备分配；设备处理； 4、文件管理功能：文件存储空间的管理；目录管理；文件的读写管理和保护； 5、用户接口：命令接口；程序接口；图形接口；","points":["处理机管理：进程控制、进程同步、进程通信、调度","存储器管理：内存分配、内存保护、地址映射、内存扩充","设备管理：缓冲管理、设备分配、设备处理","文件管理：文件存储空间的管理、目录管理、文件的读写管理和保护","用户接口：命令接口、程序接口、图形接口"],"pointsMd":["处理机管理：**进程控制**、**进程同步**、**进程通信**、**调度**","存储器管理：**内存分配**、**内存保护**、**地址映射**、**内存扩充**","设备管理：**缓冲管理**、**设备分配**、**设备处理**","文件管理：文件**存储空间的管理**、**目录管理**、文件的**读写管理和保护**","用户接口：**命令接口**、**程序接口**、**图形接口**"],"explain":"考点1.1/1.3 操作系统五大功能：（1）进程管理（处理器管理）——进程控制、进程同步、进程间通信和调度；（2）存储管理——内存的分配与回收、存储保护、内存扩充；（3）文件管理——支持文件的存储、检索和修改，解决共享、保密和保护问题；（4）设备管理——CPU和内存以外所有输入输出设备的管理；（5）用户接口——命令接口和应用程序接口。按“**处理机**、**存储**、**文件**、**设备**、**接口**”五个管理对象逐条展开。"},{"id":8,"chapter":"第一章操作系统概论","type":"blank","stem":"操作员将作业“成批”地输入到计算机中，由监督程序识别一个作业，进行处理后再取下一个作业。这种自动定序的处理方式称为“______”方式。","ref":"批处理（Batch Processing）","explanation":"批处理（Batch Processing）","blankCount":1,"blanks":[["批处理（Batch Processing）","批处理","Batch Processing"]],"explain":"考点1.2 操作系统的发展过程：手工操作→监控程序（早期**批处理**）→多道**批处理**→分时系统→UNIX→个人计算机操作系统。题眼“**成批输入**、**监督程序识别作业**、**自动定序**、**用户不干预**”即**批处理**方式：吞吐量大、交互性差。"},{"id":9,"chapter":"第一章操作系统概论","type":"blank","stem":"______是指多个用户通过终端设备与计算机交互作用来运行自己的作业，并且共享一个计算机系统而互不干扰，就好像自己有一台计算机。","ref":"分时系统","explanation":"分时系统","blankCount":1,"blanks":[["分时系统"]],"explain":"考点1.2/1.3：**分时系统**把CPU时间划分成时间片轮流为各终端服务，用户通过终端与计算机交互、共享系统而互不干扰，好像独占一台计算机。配套考点：分时操作系统四大特点——多路性、交互性、独占性、及时性。"},{"id":10,"chapter":"第一章操作系统概论","type":"blank","stem":"当代操作系统两大发展方向分别为______和______。","ref":"宏观应用、微观应用","explanation":"宏观应用、微观应用","blankCount":2,"blanks":[["宏观应用"],["微观应用"]],"unordered":true,"explain":"考点1.2：在当代，从规模上看操作系统正向着大型和微型两个不同方向发展（即押题答案的**宏观应用**与**微观应用**）：大型系统典型是分布式操作系统和机群操作系统，微型系统典型是嵌入式操作系统。"},{"id":11,"chapter":"第一章操作系统概论","type":"single","stem":"以下关于个人计算机操作系统的特点的叙述中，不正确的是（ ）","ref":"个人计算机操作系统的主要特点：计算机在某一时间内为单个用户服务采用图形界面人机交互的工作方式，界面友好使用简单方便","explanation":"个人计算机操作系统的主要特点：计算机在某一时间内为单个用户服务采用图形界面人机交互的工作方式，界面友好使用简单方便。","options":[{"key":"A","text":"使用方便，用户无须具备专门知识，也能熟练地操纵系统"},{"key":"B","text":"采用图形界面人机交互的工作方式，界面友好"},{"key":"C","text":"智能化能源管理"},{"key":"D","text":"计算机在某一时间内为单个用户服务"}],"answer":"C","explain":"个人计算机操作系统的主要特点：计算机在某一时间内为单个用户服务采用图形界面人机交互的工作方式，界面友好使用简单方便。"},{"id":12,"chapter":"第一章操作系统概论","type":"single","stem":"将大量的计算机通过网络连结在一起，可以获得极高的运算能力及广泛的数据共享。 这样一种系统称作为（ ）","ref":"分布式系统（Distributed System）将大量的计算机通过网络连结在一起，获得极高的运算能力及广泛的数据共享","explanation":"分布式系统（Distributed System）将大量的计算机通过网络连结在一起，获得极高的运算能力及广泛的数据共享","options":[{"key":"A","text":"嵌入式操作系统"},{"key":"B","text":"个人计算机操作系统"},{"key":"C","text":"网络操作系统"},{"key":"D","text":"分布式系统"}],"answer":"D","explain":"分布式系统（Distributed System）将大量的计算机通过网络连结在一起，获得极高的运算能力及广泛的数据共享"},{"id":13,"chapter":"第一章操作系统概论","type":"single","stem":"实时系统为了能够实现硬实时或软实时的要求，除了具有多道程序系统的基本能力外，还需要具有的能力不包括（ ）","ref":"实时系统为实现硬实时或软实时的要求，需要具备以下能力：（1）实时时钟管理，（2）过载防护，（3）高可靠性","explanation":"实时系统为实现硬实时或软实时的要求，需要具备以下能力：（1）实时时钟管理，（2）过载防护，（3）高可靠性。","options":[{"key":"A","text":"实时时钟管理"},{"key":"B","text":"过载防护"},{"key":"C","text":"高可靠性"},{"key":"D","text":"高精确性"}],"answer":"D","explain":"实时系统为实现硬实时或软实时的要求，需要具备以下能力：（1）实时时钟管理，（2）过载防护，（3）高可靠性。"},{"id":14,"chapter":"第一章操作系统概论","type":"blank","stem":"______系统能及时响应外部事件的请求，在规定的时间内完成对该事件的处理，并控制所有实时任务协调一致地运行。","ref":"实时操作","explanation":"实时操作","blankCount":1,"blanks":[["实时操作"]],"explain":"考点1.3 操作系统三种基本类型：批处理、分时、**实时操作**系统。题眼“及时响应外部事件、在规定时间内完成处理、控制所有实时任务协调一致运行”即**实时操作**系统的定义。配套考点：实时系统分硬实时系统与软实时系统。"},{"id":15,"chapter":"第一章操作系统概论","type":"single","stem":"按照系统的功能和特性要求，选择合适的结构， 使用相应结构设计方法将系统逐步地分解、 抽象和综合，使操作系统结构清晰、 简明、 可靠、 易读、 易修改，而且使用方便，适应性强的操作系统设计过程称为（ ）","ref":"结构设计是按照系统的功能和特性要求，选择合适的结构，使用相应结构设计方法将系统逐步地分解、抽象和综合，使操作系统结构清晰、简明、可靠、易读、易修改，而且使用方便，适应性强","explanation":"结构设计是按照系统的功能和特性要求，选择合适的结构，使用相应结构设计方法将系统逐步地分解、抽象和综合，使操作系统结构清晰、简明、可靠、易读、易修改，而且使用方便，适应性强。","options":[{"key":"A","text":"功能设计"},{"key":"B","text":"基础设计"},{"key":"C","text":"算法设计"},{"key":"D","text":"结构设计"}],"answer":"D","explain":"结构设计是按照系统的功能和特性要求，选择合适的结构，使用相应结构设计方法将系统逐步地分解、抽象和综合，使操作系统结构清晰、简明、可靠、易读、易修改，而且使用方便，适应性强。"},{"id":16,"chapter":"第一章操作系统概论","type":"single","stem":"将操作系统分成用于实现操作系统最基本功能的内核和提供各种服务的服务进程两个部分，这样的操作系统结构是（ ）","ref":"客户/服务器结构的操作系统适于应用在网络环境下分布式处理的计算环境中，又称为微内核体系结构","explanation":"客户/服务器结构的操作系统适于应用在网络环境下分布式处理的计算环境中，又称为微内核体系结构。","options":[{"key":"A","text":"层次式结构"},{"key":"B","text":"整体式结构"},{"key":"C","text":"微内核结构"},{"key":"D","text":"模块化结构"}],"answer":"C","explain":"客户/服务器结构的操作系统适于应用在网络环境下分布式处理的计算环境中，又称为微内核体系结构。"},{"id":17,"chapter":"第一章操作系统概论","type":"essay","stem":"简述微内核结构及其基本原理","ref":"微内核ＯＳ结构：能实现ＯＳ核心功能的小型内核，并非一个完整的ＯＳ，与ＯＳ的服务进程（如文件服务器、作业服务器等）共同构成ＯＳ。基本原理：只有最基本的操作系统功能才能放在内核中。不是最基本的服务和应用程序在微内核之上构造，并在用户模式下执行。微内核通常提供最小的进程和内存管理以及通信功能。微内核的主要功能是提供客户程序和运行在用户空间的各种服务之间进行通信的能力。通信以消息传递形式提供，一般采用客户/服务器模式.","explanation":"微内核ＯＳ结构：能实现ＯＳ核心功能的小型内核，并非一个完整的ＯＳ，与ＯＳ的服务进程（如文件服务器、作业服务器等）共同构成ＯＳ。基本原理：只有最基本的操作系统功能才能放在内核中。不是最基本的服务和应用程序在微内核之上构造，并在用户模式下执行。微内核通常提供最小的进程和内存管理以及通信功能。微内核的主要功能是提供客户程序和运行在用户空间的各种服务之间进行通信的能力。通信以消息传递形式提供，一般采用客户/服务器模式.","points":["微内核：能实现OS核心功能的小型内核，与服务进程共同构成OS","只有最基本的功能才能放在内核中","不是最基本的在微内核之上构造，用户模式下执行","微内核提供最小的进程和内存管理以及通信功能，通信以消息传递形式、客户/服务器模式提供"],"pointsMd":["微内核：能实现OS核心功能的**小型内核**，与**服务进程**共同构成OS","只有**最基本的功能**才能放在**内核**中","不是最基本的在**微内核之上**构造，**用户模式**下执行","微内核提供最小的进程和内存管理以及通信功能，通信以**消息传递**形式、客户/服务器模式提供"],"explain":"考点1.4 体系结构之（3）客户/服务器（微内核）结构：微内核是能实现OS核心功能的**小型内核**，并非完整的OS，与OS的**服务进程**（文件服务器、作业服务器等）共同构成操作系统。基本原理：只有**最基本的操作系统功能**（最小的进程和内存管理、进程间通信）才能放在内核中，其他服务在微内核之上构造并在用户模式下执行，以**消息传递**方式按客户/服务器模式通信。典型系统：Mach、Windows NT早期版本；缺陷主要是对效率的考虑（**消息传递**开销）。"},{"id":18,"chapter":"第一章操作系统概论","type":"blank","stem":"操作系统启动的引导方式有______和______。","ref":"BIOS引导和UEFI引导","explanation":"BIOS引导和UEFI引导","blankCount":2,"blanks":[["BIOS引导"],["UEFI引导"]],"unordered":true,"explain":"考点1.5 操作系统启动：**BIOS**是一个存储在**BIOS**芯片中的程序；启动的两种引导方式为**BIOS引导**（传统MBR）与**UEFI引导**（新一代固件，支持大容量磁盘）。"},{"id":19,"chapter":"第一章操作系统概论","type":"blank","stem":"计算机开机，______并检测第一个能够引导系统的设备，如硬盘或光驱","ref":"BIOS自检","explanation":"BIOS自检","blankCount":1,"blanks":[["BIOS自检"]],"explain":"考点1.5：计算机开机后先由**BIOS**进行加电自检并检测第一个能够引导系统的设备（硬盘、光驱等），这是启动四步中的第一步。"},{"id":20,"chapter":"第一章操作系统概论","type":"blank","stem":"操作系统的启动过程：______、 ______、 ______、 ______","ref":"BIOS自检、系统引导、启动内核、初始化系统","explanation":"BIOS自检、系统引导、启动内核、初始化系统","blankCount":4,"blanks":[["BIOS自检"],["系统引导"],["启动内核"],["初始化系统"]],"explain":"考点1.5：操作系统启动过程分四个部分：**BIOS自检**→**系统引导**→**启动内核**→**初始化系统**。按“**自检→引导→内核→初始化**”的时间顺序记忆。"},{"id":21,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"用以执行有关数据的算术和逻辑操作的是（ ）","ref":"理解指令的基本执行过程以及五种常见的指令。 算术逻辑指令：有时又称为数据处理指令，用以执行有关数据的算术和逻辑操作","explanation":"理解指令的基本执行过程以及五种常见的指令。 算术逻辑指令：有时又称为数据处理指令，用以执行有关数据的算术和逻辑操作。","options":[{"key":"A","text":"算术逻辑指令"},{"key":"B","text":"控制指令"},{"key":"C","text":"处理器控制指令"},{"key":"D","text":"访问存储器指令"}],"answer":"A","explain":"理解指令的基本执行过程以及五种常见的指令。 算术逻辑指令：有时又称为数据处理指令，用以执行有关数据的算术和逻辑操作。"},{"id":22,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"最常见的控制和状态寄存器不包括（ ）","ref":"常见的控制和状态寄存器：1）程序计数器（Program Counter，PC），它记录了将要取出的指令的地址；2）指令寄存器（Instruction Register，IR），包含了最近取出的指令；3）程序状态字（Program Status Word，PSW），它记录了处理器的运行模式信息等","explanation":"常见的控制和状态寄存器：1）程序计数器（Program Counter，PC），它记录了将要取出的指令的地址；2）指令寄存器（Instruction Register，IR），包含了最近取出的指令；3）程序状态字（Program Status Word，PSW），它记录了处理器的运行模式信息等。","options":[{"key":"A","text":"指令寄存器"},{"key":"B","text":"数据寄存器"},{"key":"C","text":"程序计数器"},{"key":"D","text":"程序状态字"}],"answer":"B","explain":"常见的控制和状态寄存器：1）程序计数器（Program Counter，PC），它记录了将要取出的指令的地址；2）指令寄存器（Instruction Register，IR），包含了最近取出的指令；3）程序状态字（Program Status Word，PSW），它记录了处理器的运行模式信息等。"},{"id":23,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"以下关于处理器工作状态的描述，正确的是（ ）","ref":"操作系统管理程序运行的状态称为管态；系统启动时，处理器的初始状态为管态；当用户程序占用处理器时，应让处理器在目态下工作。选项ACD错误","explanation":"操作系统管理程序运行的状态称为管态；系统启动时，处理器的初始状态为管态；当用户程序占用处理器时，应让处理器在目态下工作。选项ACD错误。","options":[{"key":"A","text":"操作系统管理程序运行的状态称为目态"},{"key":"B","text":"当处理器处于管态时，可以执行全部指令"},{"key":"C","text":"系统启动时，处理器的初始状态为目态"},{"key":"D","text":"当用户程序占用处理器时，应让处理器在管态下工作"}],"answer":"B","explain":"操作系统管理程序运行的状态称为管态；系统启动时，处理器的初始状态为管态；当用户程序占用处理器时，应让处理器在目态下工作。选项ACD错误。"},{"id":24,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"程序状态字的内容不包含（ ）","ref":"处理器的状态字（PSW）通常包括以下状态代码。1）CPU的工作状态代码2）条件码3）中断屏蔽码","explanation":"处理器的状态字（PSW）通常包括以下状态代码。1）CPU的工作状态代码2）条件码3）中断屏蔽码","options":[{"key":"A","text":"CPU的工作状态代码"},{"key":"B","text":"条件码"},{"key":"C","text":"中断屏蔽码"},{"key":"D","text":"执行代码的用户ID"}],"answer":"D","explain":"处理器的状态字（PSW）通常包括以下状态代码。1）CPU的工作状态代码2）条件码3）中断屏蔽码"},{"id":25,"chapter":"第二章操作系统运行环境与运行机制","type":"blank","stem":"所有的子系统都可以包括在______和______这两个层次中","ref":"硬件（子）系统和软件（子）系统","explanation":"硬件（子）系统和软件（子）系统","blankCount":2,"blanks":[["硬件（子）系统","硬件系统"],["软件（子）系统","软件系统"]],"unordered":true,"explain":"考点2.1 计算机系统的层次结构：所有子系统都可以包括在**硬件（子）系统**和**软件（子）系统**这两个层次中。"},{"id":26,"chapter":"第二章操作系统运行环境与运行机制","type":"blank","stem":"系统软件包括______、 ______、 ______。","ref":"操作系统，编译系统，数据库","explanation":"操作系统，编译系统，数据库。","blankCount":3,"blanks":[["操作系统"],["编译系统"],["数据库"]],"unordered":true,"explain":"考点2.1：软件系统可进一步划分为**系统软件**、**支撑软件**和**应用软件**三个层次；**系统软件**以**操作系统**、**编译系统**为代表，**数据库**及各种接口软件、开发工具属**支撑软件**。押题答案列举的三类代表：**操作系统**、**编译系统**、**数据库**。"},{"id":27,"chapter":"第二章操作系统运行环境与运行机制","type":"blank","stem":"硬件系统包括______、 ______、 ______、 ______、 ______。","ref":"中央处理器、存储系统、中断机制、I／O技术、时钟","explanation":"中央处理器、存储系统、中断机制、I／O技术、时钟。","blankCount":5,"blanks":[["中央处理器"],["存储系统"],["中断机制"],["I／O技术"],["时钟"]],"unordered":true,"explain":"考点2.1：硬件系统包括**中央处理器**、内存、外存储器（磁盘、磁带等）以及各种输入输出设备（键盘、鼠标、显示器、打印机等）。押题答案按教材章节结构归纳为五部分：**中央处理器**、**存储系统**、**中断机制**、I/O技术、**时钟**。"},{"id":28,"chapter":"第二章操作系统运行环境与运行机制","type":"essay","stem":"软件系统包括哪些软件?请举例说明。","ref":"软件系统包括系统软件、支撑软件和应用软件。操作系统、编译系统等是系统软件，数据库、各种接口软件、软件开发工具等是支撑软件，财务管理、人口普查等专用程序是应用软件","explanation":"软件系统包括系统软件、支撑软件和应用软件。操作系统、编译系统等是系统软件，数据库、各种接口软件、软件开发工具等是支撑软件，财务管理、人口普查等专用程序是应用软件。","points":["系统软件、支撑软件、应用软件","操作系统、编译系统等是系统软件；数据库、软件开发工具等是支撑软件；财务管理、人口普查等是应用软件"],"pointsMd":["**系统软件**、**支撑软件**、**应用软件**","**操作系统**、**编译系统**等是系统软件；**数据库**、**软件开发工具**等是支撑软件；**财务管理**、**人口普查**等是应用软件"],"explain":"考点2.1：软件系统可以进一步划分为**系统软件**、**支撑软件**和**应用软件**三个层次。举例：操作系统、编译系统等是**系统软件**；数据库、各种接口软件、软件开发工具等是**支撑软件**；财务管理、人口普查等专用程序是**应用软件**。答题格式“**分类+举例**”，三类不可缺。"},{"id":29,"chapter":"第二章操作系统运行环境与运行机制","type":"essay","stem":"简述指令的执行过程。","ref":"（1）每个取值周期先从存储器中读取一条指令（2）在取指令完成后，根据指令类别将程序计数器的值变成下一条指令的地址，通常是自增1（3）取到的指令被放在处理器的指令寄存器中（4）处理器解释并执行命令","explanation":"（1）每个取值周期先从存储器中读取一条指令（2）在取指令完成后，根据指令类别将程序计数器的值变成下一条指令的地址，通常是自增1（3）取到的指令被放在处理器的指令寄存器中（4）处理器解释并执行命令","points":["取值周期从存储器中读取一条指令","取指完成后，程序计数器的值变成下一条指令的地址，通常自增1","取到的指令放在处理器的指令寄存器中","处理器解释并执行命令"],"pointsMd":["取值周期从**存储器**中读取一条指令","取指完成后，**程序计数器**的值变成**下一条指令的地址**，通常**自增1**","取到的指令放在处理器的**指令寄存器**中","处理器**解释并执行**命令"],"explain":"考点2.2 指令执行的基本过程：最简单的指令处理方式——首先，处理器每次从存储器中读取一条指令，并在取指令完成后，根据指令类别自动将**程序计数器**（PC）的值变成下一条指令的地址，通常是自增1；其次，取到的指令被存储在处理器的**指令寄存器**（IR）中，处理器于是解释并执行这条指令。四步：取指→PC形成下一地址→指令入IR→解释执行。"},{"id":30,"chapter":"第二章操作系统运行环境与运行机制","type":"essay","stem":"简述指令的分类。","ref":"（1）访问存储器指令：负责处理器和存储器之间的数据传送（2）I/O指令：负责处理器和I/O模块之间的数据传送和命令发送（3）算术逻辑指令（数据处理指令）：用以执行有关数据的算术和逻辑操作（4）控制转移指令：这种指令可以指定一个新的指令的执行起点（5）处理器控制指令：这种指令用于修改处理器状态，改变处理器工作方式","explanation":"（1）访问存储器指令：负责处理器和存储器之间的数据传送（2）I/O指令：负责处理器和I/O模块之间的数据传送和命令发送（3）算术逻辑指令（数据处理指令）：用以执行有关数据的算术和逻辑操作（4）控制转移指令：这种指令可以指定一个新的指令的执行起点（5）处理器控制指令：这种指令用于修改处理器状态，改变处理器工作方式","points":["访问存储器指令：处理器和存储器之间的数据传送","I/O指令：处理器和I/O模块之间的数据传送和命令发送","算术逻辑指令：执行有关数据的算术和逻辑操作","控制转移指令：指定一个新的指令的执行起点","处理器控制指令：修改处理器状态，改变处理器工作方式"],"pointsMd":["访问存储器指令：处理器和存储器之间的**数据传送**","I/O指令：处理器和I/O模块之间的数据传送和**命令发送**","算术逻辑指令：执行有关数据的**算术和逻辑操作**","控制转移指令：指定一个新的指令的**执行起点**","处理器控制指令：修改处理器状态，改变处理器**工作方式**"],"explain":"考点2.2：指令大致可以分成五类——（1）访问存储器指令：负责处理器和存储器之间的数据传送；（2）I/O指令：负责处理器和I/O模块之间的数据传送和命令发送；（3）算术逻辑指令（数据处理指令）：执行有关数据的算术和逻辑操作；（4）控制转移指令：指定一个新的指令的执行起点；（5）处理器控制指令：修改处理器状态、改变工作方式。口诀“**访存**、I/O、**算逻**、**转移**、**控处**”。"},{"id":31,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"可用作随机存取数据的存储器是（ ）","ref":"1）读写型的存储器，这种类型的存储器常被称为随机访问存储器（Random Access Memory，RAM）。RAM主要用作存储随机存取的程序的数据。2）只读型的存储器，（Read-Only Memory，ROM）","explanation":"1）读写型的存储器，这种类型的存储器常被称为随机访问存储器（Random Access Memory，RAM）。RAM主要用作存储随机存取的程序的数据。2）只读型的存储器，（Read-Only Memory，ROM）。","options":[{"key":"A","text":"RAM"},{"key":"B","text":"ROM"},{"key":"C","text":"PROM"},{"key":"D","text":"EPROM"}],"answer":"A","explain":"1）读写型的存储器，这种类型的存储器常被称为随机访问存储器（Random Access Memory，RAM）。RAM主要用作存储随机存取的程序的数据。2）只读型的存储器，（Read-Only Memory，ROM）。"},{"id":32,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"内存空间的最小分配单位是（ ）","ref":"在为用户分配内存空间时，以块为最小单位，这样的块有时被称为一个物理页（Page）","explanation":"在为用户分配内存空间时，以块为最小单位，这样的块有时被称为一个物理页（Page）。","options":[{"key":"A","text":"二进位"},{"key":"B","text":"字节"},{"key":"C","text":"字"},{"key":"D","text":"块"}],"answer":"D","explain":"在为用户分配内存空间时，以块为最小单位，这样的块有时被称为一个物理页（Page）。"},{"id":33,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"以下可用于存储保护的技术是（ ）","ref":"要实现存储保护，必须要有硬件的支持。 界地址寄存器是被广泛使用的一种存储保护技术","explanation":"要实现存储保护，必须要有硬件的支持。 界地址寄存器是被广泛使用的一种存储保护技术。","options":[{"key":"A","text":"缓冲技术"},{"key":"B","text":"DMA技术"},{"key":"C","text":"通道技术"},{"key":"D","text":"界地址寄存器"}],"answer":"D","explain":"要实现存储保护，必须要有硬件的支持。 界地址寄存器是被广泛使用的一种存储保护技术。"},{"id":34,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"由处理器内部的计时器产生，允许操作系统以一定规律执行函数的是（ ）","ref":"时钟中断：由处理器内部的计时器产生，允许操作系统以一定规律执行函数，如时间片到时、硬件实时钟到时等","explanation":"时钟中断：由处理器内部的计时器产生，允许操作系统以一定规律执行函数，如时间片到时、硬件实时钟到时等。","options":[{"key":"A","text":"硬件故障中断"},{"key":"B","text":"控制台中断"},{"key":"C","text":"输入输出中断"},{"key":"D","text":"时钟中断"}],"answer":"D","explain":"时钟中断：由处理器内部的计时器产生，允许操作系统以一定规律执行函数，如时间片到时、硬件实时钟到时等。"},{"id":35,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"在某些条件下由指令执行结果产生的典型异常是（ ）","ref":"程序性中断：某些条件下由指令执行结果产生，例如算术溢出、被零除、目态程序试图执行非法指令、访问不被允许访问的存储位置、虚拟存储中的缺页等","explanation":"程序性中断：某些条件下由指令执行结果产生，例如算术溢出、被零除、目态程序试图执行非法指令、访问不被允许访问的存储位置、虚拟存储中的缺页等。","options":[{"key":"A","text":"时钟中断"},{"key":"B","text":"访管指令异常"},{"key":"C","text":"程序性中断"},{"key":"D","text":"控制台中断"}],"answer":"C","explain":"程序性中断：某些条件下由指令执行结果产生，例如算术溢出、被零除、目态程序试图执行非法指令、访问不被允许访问的存储位置、虚拟存储中的缺页等。"},{"id":36,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"时钟中断处理程序的主要内容不包括（ ）","ref":"时钟中断①维护软件时钟。②处理器调度。③控制系统定时任务。④实时处理","explanation":"时钟中断①维护软件时钟。②处理器调度。③控制系统定时任务。④实时处理","options":[{"key":"A","text":"维护软件时钟"},{"key":"B","text":"监控管理"},{"key":"C","text":"处理器调度"},{"key":"D","text":"实时处理"}],"answer":"B","explain":"时钟中断①维护软件时钟。②处理器调度。③控制系统定时任务。④实时处理"},{"id":37,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"需要做的工作是保存现场，使用一定的手段警告管理员并提供一些辅助的诊断信息的是（ ）","ref":"硬件故障一般是由硬件的问题引起的，排除此类故障通常需要人工的干预，例如复位硬件或者更换设备等。 需要做的工作是保存现场，使用一定的手段警告管理员并提供一些辅助的诊断信息","explanation":"硬件故障一般是由硬件的问题引起的，排除此类故障通常需要人工的干预，例如复位硬件或者更换设备等。 需要做的工作是保存现场，使用一定的手段警告管理员并提供一些辅助的诊断信息。","options":[{"key":"A","text":"硬件故障中断处理程序"},{"key":"B","text":"时钟中断处理程序"},{"key":"C","text":"程序性中断处理程序"},{"key":"D","text":"自愿性中断处理程序"}],"answer":"A","explain":"硬件故障一般是由硬件的问题引起的，排除此类故障通常需要人工的干预，例如复位硬件或者更换设备等。 需要做的工作是保存现场，使用一定的手段警告管理员并提供一些辅助的诊断信息。"},{"id":38,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"中断按照优先度分级，允许优先级较高的中断打断优先级较低的中断处理过程称为（ ）","ref":"多个中断的处理策略一般有如下两种：第二种（中断嵌套）更优正当处理一个中断时禁止其他中断，此时系统将对任何新发生的中断置之不理允许优先级较高的中断打断优先级较低的中断处理过程，引起中断嵌套","explanation":"多个中断的处理策略一般有如下两种：第二种（中断嵌套）更优正当处理一个中断时禁止其他中断，此时系统将对任何新发生的中断置之不理允许优先级较高的中断打断优先级较低的中断处理过程，引起中断嵌套","options":[{"key":"A","text":"中断断点"},{"key":"B","text":"中断响应"},{"key":"C","text":"中断嵌套"},{"key":"D","text":"中断事件"}],"answer":"C","explain":"多个中断的处理策略一般有如下两种：第二种（中断嵌套）更优正当处理一个中断时禁止其他中断，此时系统将对任何新发生的中断置之不理允许优先级较高的中断打断优先级较低的中断处理过程，引起中断嵌套"},{"id":39,"chapter":"第二章操作系统运行环境与运行机制","type":"single","stem":"把由于系统调用引起处理器中断的指令称为（ ）","ref":"在系统中为控制系统调用服务的机构称为陷入（Trap）或异常处理机构。与此相对应，把由于系统调用引起处理器中断的指令称为陷入或异常指令（或称访管指令）","explanation":"在系统中为控制系统调用服务的机构称为陷入（Trap）或异常处理机构。与此相对应，把由于系统调用引起处理器中断的指令称为陷入或异常指令（或称访管指令）","options":[{"key":"A","text":"机器指令"},{"key":"B","text":"系统调用命令"},{"key":"C","text":"陷入或异常指令"},{"key":"D","text":"特权指令"}],"answer":"C","explain":"在系统中为控制系统调用服务的机构称为陷入（Trap）或异常处理机构。与此相对应，把由于系统调用引起处理器中断的指令称为陷入或异常指令（或称访管指令）"},{"id":40,"chapter":"第二章操作系统运行环境与运行机制","type":"essay","stem":"现代计算机系统采用的多级存储体系包括哪几部分?简述各部分的功能。","ref":"多级存储体系包括寄存器、主存储器、高速缓冲存储器和辅助存储器。寄存器用来存放处理器的工作信息主存储器用来存放当前要执行的程序和数据高速缓冲存储器用来存放当前经常要使用的信息辅助存储器作为主存储器的扩展，用来存放大量的程序和数据","explanation":"多级存储体系包括寄存器、主存储器、高速缓冲存储器和辅助存储器。寄存器用来存放处理器的工作信息主存储器用来存放当前要执行的程序和数据高速缓冲存储器用来存放当前经常要使用的信息辅助存储器作为主存储器的扩展，用来存放大量的程序和数据","points":["寄存器、主存储器、高速缓冲存储器、辅助存储器","寄存器：存放处理器的工作信息","主存储器：存放当前要执行的程序和数据","高速缓冲存储器：存放当前经常要使用的信息","辅助存储器：主存储器的扩展，存放大量的程序和数据"],"pointsMd":["**寄存器**、**主存储器**、**高速缓冲存储器**、**辅助存储器**","寄存器：存放处理器的**工作信息**","主存储器：存放**当前要执行**的程序和数据","高速缓冲存储器：存放当前**经常要使用**的信息","辅助存储器：主存储器的**扩展**，存放大量的程序和数据"],"explain":"考点2.3 存储系统：多级存储体系包括**寄存器**、**高速缓冲存储器**、**主存储器**、**辅助存储器**。**寄存器**存放处理器的**工作信息**（在CPU内，最快）；**高速缓冲存储器**存放当前**经常要使用**的信息（缓解CPU与主存速度差）；**主存储器**存放**当前要执行**的程序和数据；**辅助存储器**作为主存的扩展，存放大量的程序和数据。从内到外：速度递减、容量递增、位价递减。"},{"id":41,"chapter":"第二章操作系统运行环境与运行机制","type":"essay","stem":"何为中断响应?中断处理程序主要工作有哪些方面?","ref":"处理器每执行完一条指令后，中断装置立即检查有无中断事件发生。若有中断事件发生，则暂停现行进程的执行，而让操作系统的中断处理程序占用处理器。中断处理程序主要工作如下：①保护被中断进程的现场信息②分析中断原因③处理发生的中断事件","explanation":"处理器每执行完一条指令后，中断装置立即检查有无中断事件发生。若有中断事件发生，则暂停现行进程的执行，而让操作系统的中断处理程序占用处理器。中断处理程序主要工作如下：①保护被中断进程的现场信息②分析中断原因③处理发生的中断事件","points":["每执行完一条指令后立即检查有无中断事件，有则暂停现行进程，让操作系统的中断处理程序占用处理器","保护被中断进程的现场信息","分析中断原因","处理发生的中断事件"],"pointsMd":["每执行完一条指令后立即检查有无**中断事件**，有则**暂停现行进程**，让操作系统的**中断处理程序**占用处理器","保护被中断进程的**现场信息**","分析**中断原因**","处理发生的**中断事件**"],"explain":"考点2.4 中断机制：中断是指CPU对系统中或系统外发生的**异步事件**的响应。中断响应：处理器每执行完一条指令后，中断装置立即检查有无中断事件发生，若有则暂停现行进程的执行，让操作系统的中断处理程序占用处理器。中断处理程序的主要工作：①保护被中断进程的现场信息；②分析中断原因；③处理发生的中断事件（并**恢复现场**返回）。"},{"id":42,"chapter":"第二章操作系统运行环境与运行机制","type":"blank","stem":"有了通道后，只要______启动了通道，通道就自行控制外设与______间的信息传输，使CPU可以与设备并行工作。","ref":"中央处理器、主存","explanation":"中央处理器、主存、","blankCount":2,"blanks":[["中央处理器"],["主存"]],"explain":"考点2.5 I/O技术：通道是**独立于处理器**、专门负责数据I/O传输工作的处理单元。有了通道，CPU（**中央处理器**）只需下达启动命令，通道就自行控制外设与**主存**间的信息传输，使CPU与设备并行工作。"},{"id":43,"chapter":"第二章操作系统运行环境与运行机制","type":"blank","stem":"通过系统总线中的一个独立控制单元______，自动地控制成块数据在内存和I/O 单元之间的传送。","ref":"DMA 控制器","explanation":"DMA 控制器","blankCount":1,"blanks":[["DMA 控制器"]],"explain":"考点2.5：**DMA**（直接存储器访问）技术通过系统总线中的一个独立控制单元——**DMA**控制器，自动地控制成块数据在内存和I/O单元之间的传送，不经过CPU逐字节搬运。"},{"id":44,"chapter":"第二章操作系统运行环境与运行机制","type":"essay","stem":"简述通道的工作原理。","ref":"当处理器执行到一条“启动外设”的指令时，就按指令中给定的参数启动指定的设备设备启动之后，对该外部设备的控制权转移到通道该外部设备与主存储器之间发生的信息传送，由通道控制该外部设备工作结束后，会产生形成一个“输入输出操作结束”的I/O中断事件","explanation":"当处理器执行到一条“启动外设”的指令时，就按指令中给定的参数启动指定的设备设备启动之后，对该外部设备的控制权转移到通道该外部设备与主存储器之间发生的信息传送，由通道控制该外部设备工作结束后，会产生形成一个“输入输出操作结束”的I/O中断事件","points":["执行到一条启动外设的指令时，按指令中给定的参数启动指定的设备","对该外部设备的控制权转移到通道","外部设备与主存储器之间的信息传送，由通道控制","外部设备工作结束后，形成输入输出操作结束的I/O中断事件"],"pointsMd":["执行到一条启动外设的指令时，按指令中给定的参数**启动指定的设备**","对该外部设备的**控制权**转移到通道","外部设备与主存储器之间的信息传送，由**通道控制**","外部设备工作结束后，形成**输入输出操作结束**的I/O中断事件"],"explain":"考点2.5/7.3 通道的工作原理：当处理器执行到一条“**启动外设**”的指令时，就按指令中给定的参数启动指定的设备；设备启动之后，对该外部设备的**控制权**转移到通道；该设备与主存储器之间的信息传送由**通道控制**（接受CPU指令、执行通道程序、组织数据传输、收集状态信息）；设备工作结束后，通道形成一个“**输入输出操作结束**”中断事件通知CPU。意义：CPU从数据传送中解脱，与外设**并行工作**。"},{"id":45,"chapter":"第二章操作系统运行环境与运行机制","type":"blank","stem":"时钟分成______和______两类。","ref":"硬件时钟和软件时钟","explanation":"硬件时钟和软件时钟","blankCount":2,"blanks":[["硬件时钟"],["软件时钟"]],"unordered":true,"explain":"考点2.6 时钟：一般分成**硬件时钟**和**软件时钟**两类；按其用途又可分为**绝对时钟**和**相对时钟**，注意区分两种划分标准。"},{"id":46,"chapter":"第二章操作系统运行环境与运行机制","type":"essay","stem":"简述时钟的工作原理。","ref":"硬件时钟工作原理：电路中的晶体振荡器，每隔一定间隔产生固定的脉冲频率，时钟电路中的时钟寄存器依据时钟电路所产生的脉冲数，对时钟寄存器进行加1的工作软件时钟工作原理：利用内存单元模拟时钟寄存器，采用一段程序来计算相应的脉冲数，对内存时钟寄存器进行加1或减1的工作","explanation":"硬件时钟工作原理：电路中的晶体振荡器，每隔一定间隔产生固定的脉冲频率，时钟电路中的时钟寄存器依据时钟电路所产生的脉冲数，对时钟寄存器进行加1的工作软件时钟工作原理：利用内存单元模拟时钟寄存器，采用一段程序来计算相应的脉冲数，对内存时钟寄存器进行加1或减1的工作。","points":["硬件时钟：晶体振荡器每隔一定间隔产生固定的脉冲频率，时钟寄存器进行加1","软件时钟：利用内存单元模拟时钟寄存器，程序计算相应的脉冲数，加1或减1"],"pointsMd":["硬件时钟：**晶体振荡器**每隔一定间隔产生固定的脉冲频率，时钟寄存器进行**加1**","软件时钟：利用内存单元**模拟时钟寄存器**，程序计算相应的脉冲数，加1或减1"],"explain":"考点2.6 时钟：硬件时钟工作原理——电路中的**晶体振荡器**每隔一定间隔产生固定的脉冲频率，时钟电路中的**时钟寄存器**依据**脉冲数**对寄存器加1计数；软件时钟工作原理——利用内存单元模拟**时钟寄存器**，采用一段程序来计算相应的**脉冲数**。"},{"id":47,"chapter":"第二章操作系统运行环境与运行机制","type":"essay","stem":"简述时钟的功能。","ref":"时钟可以为计算机完成以下工作： （1）在多道程序运行，时钟可以发现死循环，防止机时的浪费（2）在分时系统中，用时钟实现时间片轮转运行（3）在实时系统中，按要求的时间间隔输出信号控制设备（4）定时唤醒外部事件（5）记录用户和系统所需要的绝对时间，即年、月、日","explanation":"时钟可以为计算机完成以下工作： （1）在多道程序运行，时钟可以发现死循环，防止机时的浪费（2）在分时系统中，用时钟实现时间片轮转运行（3）在实时系统中，按要求的时间间隔输出信号控制设备（4）定时唤醒外部事件（5）记录用户和系统所需要的绝对时间，即年、月、日","points":["多道程序运行时发现死循环，防止机时的浪费","分时系统中用时钟实现时间片轮转运行","实时系统中按要求的时间间隔输出信号控制设备","定时唤醒外部事件","记录用户和系统所需要的绝对时间"],"pointsMd":["多道程序运行时发现**死循环**，防止机时的浪费","分时系统中用时钟实现**时间片轮转**运行","实时系统中按要求的**时间间隔**输出信号控制设备","**定时唤醒**外部事件","记录用户和系统所需要的**绝对时间**"],"explain":"考点2.6 时钟的功能：（1）多道程序运行时发现**死循环**，防止机时浪费；（2）分时系统中用时钟实现**时间片轮转**运行；（3）实时系统中按要求的**时间间隔**输出信号控制设备；（4）**定时唤醒**外部事件；（5）记录**用户使用机时**。按“**防死循环**、**时间片**、**实时控制**、**定时唤醒**、**记机时**”五个场景记。"},{"id":48,"chapter":"第二章操作系统运行环境与运行机制","type":"blank","stem":"______是操作系统提供给编程人员的唯一接口。","ref":"系统调用","explanation":"系统调用","blankCount":1,"blanks":[["系统调用"]],"explain":"考点2.7 系统调用：所谓**系统调用**，就是用户在程序中调用操作系统所提供的一些子功能。它对应考点1.3用户接口中的“**应用程序接口**（**程序接口**）”，是操作系统提供给编程人员的唯一接口。"},{"id":49,"chapter":"第二章操作系统运行环境与运行机制","type":"essay","stem":"简述系统调用的分类。","ref":"一个操作系统的功能分为两大部分：一部分是系统自身所需要的；另一部分功能是作为服务提供给用户的，有关这部分功能可以从操作系统所提供的系统调用上体现出来。（1）进程控制类系统调用（2）文件操作类系统调用（3）进程通信类系统调用（4）设备管理类系统调用（5）信息维护类系统调用","explanation":"一个操作系统的功能分为两大部分：一部分是系统自身所需要的；另一部分功能是作为服务提供给用户的，有关这部分功能可以从操作系统所提供的系统调用上体现出来。（1）进程控制类系统调用（2）文件操作类系统调用（3）进程通信类系统调用（4）设备管理类系统调用（5）信息维护类系统调用","points":["进程控制类","文件操作类","进程通信类","设备管理类","信息维护类"],"pointsMd":["**进程控制类**","**文件操作类**","**进程通信类**","**设备管理类**","**信息维护类**"],"explain":"考点2.7 系统调用的分类五类：（1）**进程控制类**系统调用；（2）**文件操作类**系统调用；（3）**进程通信类**系统调用；（4）**设备管理类**系统调用；（5）**信息维护类**系统调用。系统调用就是用户在程序中调用操作系统所提供的一些**子功能**。"},{"id":50,"chapter":"第三章进程","type":"single","stem":"进程从运行状态进入就绪状态的原因可能是（ ）","ref":"运行→就绪,规定的运行时间片用完","explanation":"运行→就绪,规定的运行时间片用完","options":[{"key":"A","text":"被进程调度程序选中"},{"key":"B","text":"等待某一事件的发生"},{"key":"C","text":"等待的事件已发生"},{"key":"D","text":"时间片用完"}],"answer":"D","explain":"运行→就绪,规定的运行时间片用完"},{"id":51,"chapter":"第三章进程","type":"blank","stem":"______是具有一定独立功能的程序在某个数据集合上的一次运行活动，是系统进行资源分配和调度的一个独立单位","ref":"进程","explanation":"进程。","blankCount":1,"blanks":[["进程"]],"explain":"考点3.1 进程的基本概念：**进程**是具有一定独立功能的程序在某个数据集合上的运行活动，是操作系统进行资源分配和调度的独立单位。注意配套结论：程序是静态的，**进程**是动态的。"},{"id":52,"chapter":"第三章进程","type":"blank","stem":"七状态模型状态五状态进程模型相比，增加了______和______两个状态","ref":"就绪挂起和阻塞挂起","explanation":"就绪挂起和阻塞挂起。","blankCount":2,"blanks":[["就绪挂起"],["阻塞挂起"]],"unordered":true,"explain":"考点3.1 七状态进程模型：在五状态模型（创建、就绪、运行、阻塞、退出）基础上增加“**挂起**/**激活**”转换，多出**就绪挂起**和**阻塞挂起**两个状态（进程被换出到外存）。"},{"id":53,"chapter":"第三章进程","type":"blank","stem":"为了便于管理，操作系统把所有的PCB用适当方式组织起来。一般的组织方式有：线性方式、 ______和______。","ref":"索引方式链接方式","explanation":"索引方式链接方式","blankCount":2,"blanks":[["索引方式"],["链接方式"]],"unordered":true,"explain":"考点3.1：PCB（进程控制块）的内容分**调度信息**和**现场信息**两大部分；PCB的组织方式有三种：**线性方式**、**索引方式**、**链接方式**。"},{"id":54,"chapter":"第三章进程","type":"essay","stem":"在七状态进程模型中，什么是阻塞状态？什么是阻塞挂起状态?两个状态之间如何转换？","ref":"阻塞状态（Blocked）：进程在内存并等待某事件的出现。阻塞挂起状态（Blocked，Suspend）：进程在外存并等待某事件的出现。没有进程处于就绪状态或就绪进程要求更多内存资源时，就会把阻塞状态变成阻塞挂起状态。当一个进程释放足够内存时，系统会把一个高优先级阻塞挂起进程激活，由阻塞挂起状态变成阻塞状态","explanation":"阻塞状态（Blocked）：进程在内存并等待某事件的出现。阻塞挂起状态（Blocked，Suspend）：进程在外存并等待某事件的出现。没有进程处于就绪状态或就绪进程要求更多内存资源时，就会把阻塞状态变成阻塞挂起状态。当一个进程释放足够内存时，系统会把一个高优先级阻塞挂起进程激活，由阻塞挂起状态变成阻塞状态。","points":["阻塞状态：进程在内存并等待某事件的出现","阻塞挂起状态：进程在外存并等待某事件的出现","没有进程处于就绪状态或就绪进程要求更多内存时，阻塞变成阻塞挂起","一个进程释放足够内存时，高优先级阻塞挂起进程被激活，变回阻塞状态"],"pointsMd":["阻塞状态：进程**在内存**并等待某事件的出现","阻塞挂起状态：进程**在外存**并等待某事件的出现","没有进程处于就绪状态或就绪进程要求更多内存时，阻塞变成**阻塞挂起**","一个进程释放足够内存时，**高优先级**阻塞挂起进程被激活，变回阻塞状态"],"explain":"考点3.1 七状态进程模型：阻塞状态（Blocked）——进程在内存并等待某事件的出现；阻塞挂起状态（Blocked, Suspend）——进程**在外存**并等待某事件的出现。转换：没有进程处于就绪状态或就绪进程要求更多内存资源时，把阻塞状态变成阻塞挂起状态（挂起换出到外存）；当一个进程释放足够内存时，系统把一个**高优先级**阻塞挂起进程激活，由阻塞挂起状态变成阻塞状态。两态本质区别只在“**在内存还是在外存**”。"},{"id":55,"chapter":"第三章进程","type":"essay","stem":"简述进程具有哪些特性。","ref":"进程具有以下特性：（1）并发性：一个进程可以同其他进程一道向前推进（2）动态性：进程有其生命周期，且进程的状态是不断变化的（3）独立性：一个进程是一个相对完整的资源分配单位（4）交往性：一个进程在运行过程中可能会与其他进程发生直接的或间接的相互作用（5）异步性：每个进程按照各自独立的、不可预知的速度向前推进（6）结构性：一个进程由程序、数据和进程控制块三部分组成","explanation":"进程具有以下特性：（1）并发性：一个进程可以同其他进程一道向前推进（2）动态性：进程有其生命周期，且进程的状态是不断变化的（3）独立性：一个进程是一个相对完整的资源分配单位（4）交往性：一个进程在运行过程中可能会与其他进程发生直接的或间接的相互作用（5）异步性：每个进程按照各自独立的、不可预知的速度向前推进（6）结构性：一个进程由程序、数据和进程控制块三部分组成","points":["并发性：可以同其他进程一道向前推进","动态性：有生命周期，状态不断变化","独立性：相对完整的资源分配单位","交往性：运行中与其他进程发生相互作用","异步性：按各自独立的、不可预知的速度向前推进","结构性：由程序、数据和进程控制块三部分组成"],"pointsMd":["并发性：可以同其他进程一道**向前推进**","动态性：有**生命周期**，状态不断变化","独立性：相对完整的**资源分配**单位","交往性：运行中与其他进程发生**相互作用**","异步性：按各自独立的、**不可预知**的速度向前推进","结构性：由程序、数据和**进程控制块**三部分组成"],"explain":"考点3.1 进程的特征六条：（1）并发性——可同其他进程一道向前推进；（2）动态性——有生命周期，状态不断变化（最本质的特征）；（3）独立性——一个相对完整的资源分配单位；（4）交互性（交往性）——运行中可能与其他进程发生直接或间接的相互作用；（5）异步性——按各自独立的、不可预知的速度向前推进；（6）结构性——一个进程由程序、数据和进程控制块（PCB）三部分组成。口诀“**并动独交异结**”。"},{"id":56,"chapter":"第三章进程","type":"single","stem":"以下关于线程的属性的叙述中，正确的是（ ）","ref":"每个线程有一个标识符和一张线程描述表。不同的线程可以执行相同的程序。多个线程是可以并发执行的。 ACD错误","explanation":"每个线程有一个标识符和一张线程描述表。不同的线程可以执行相同的程序。多个线程是可以并发执行的。 ACD错误。","options":[{"key":"A","text":"每个线程有多个标识符和一张线程描述表"},{"key":"B","text":"同一个进程中的各个线程共享该进程的内存地址空间"},{"key":"C","text":"不同的线程不可以执行相同的程序"},{"key":"D","text":"多个线程是不可以并发执行的"}],"answer":"B","explain":"每个线程有一个标识符和一张线程描述表。不同的线程可以执行相同的程序。多个线程是可以并发执行的。 ACD错误。"},{"id":57,"chapter":"第三章进程","type":"single","stem":"以下关于进程和线程的说法中，错误的是（ ）","ref":"线程是进程中的一个实体，是处理器调度和分派的基本单位。线程自己基本上不拥有系统资源，只拥有少量在运行中必不可少的资源，但它可与同属一个进程的其他线程共享进程所拥有的全部资源","explanation":"线程是进程中的一个实体，是处理器调度和分派的基本单位。线程自己基本上不拥有系统资源，只拥有少量在运行中必不可少的资源，但它可与同属一个进程的其他线程共享进程所拥有的全部资源。","options":[{"key":"A","text":"线程是资源的分配单位"},{"key":"B","text":"线程是进程中的一个实体"},{"key":"C","text":"线程是处理器的独立调度单位"},{"key":"D","text":"一个进程可以包含一个或多个线程"}],"answer":"A","explain":"线程是进程中的一个实体，是处理器调度和分派的基本单位。线程自己基本上不拥有系统资源，只拥有少量在运行中必不可少的资源，但它可与同属一个进程的其他线程共享进程所拥有的全部资源。"},{"id":58,"chapter":"第三章进程","type":"single","stem":"以下关于用户级线程的叙述中，不正确的是（ ）","ref":"用户级线程不依赖于内核","explanation":"用户级线程不依赖于内核。","options":[{"key":"A","text":"用户级线程依赖于内核"},{"key":"B","text":"用户级线程只存在于用户态中"},{"key":"C","text":"用户级线程包可以在不支持线程的操作系统上实现"},{"key":"D","text":"用户级线程允许每个进程有自己定制的调度算法"}],"answer":"A","explain":"用户级线程不依赖于内核。"},{"id":59,"chapter":"第三章进程","type":"blank","stem":"对进程在整个生命周期中各种状态之间的转换进行有效的控制通过______来实现","ref":"进程控制原语","explanation":"进程控制原语","blankCount":1,"blanks":[["进程控制原语"]],"explain":"考点3.2 进程控制：用于进程控制的原语一般有**创建原语**、**撤销原语**、**挂起原语**、**激活原语**、**阻塞原语**、**唤醒原语**以及改变进程优先级原语等，进程各状态间的转换正是靠这些原语实现。"},{"id":60,"chapter":"第三章进程","type":"blank","stem":"______由若干条指令所组成的一个指令序列，用来实现某个特定的操作功能连续的，具有不可分割性，在执行时也不可间断必须在管态下执行，并且常驻内存。","ref":"原语","explanation":"原语","blankCount":1,"blanks":[["原语"]],"explain":"考点3.2：所谓**原语**，是由若干条指令组成的一个指令序列，用来实现某个特定的操作功能。配套特征（押题题干所述）：不可分割、执行时不可间断、必须在管态（内核态）下执行、常驻内存。"},{"id":61,"chapter":"第三章进程","type":"blank","stem":"______是创建一个新的进程，前者称为父进程，后者称为子进程建立进程控制块PCB","ref":"创建原语","explanation":"创建原语。","blankCount":1,"blanks":[["创建原语"]],"explain":"考点3.2：**创建原语**用于创建一个新进程——前者为父进程，后者为子进程，并为子进程建立进程控制块PCB。"},{"id":62,"chapter":"第三章进程","type":"blank","stem":"引入线程的操作系统中______作为调度和分派的基本单位，______作为资源拥有的基本单位。","ref":"线程、进程","explanation":"线程、进程。","blankCount":2,"blanks":[["线程"],["进程"]],"explain":"考点3.3/3.4：在引入**线程**的操作系统中，**线程**是**进程**中的一个实体，是CPU调度和分派的基本单位；**进程**仍是资源分配的基本单位。口诀“**线程**调度、**进程**资源”。"},{"id":63,"chapter":"第三章进程","type":"blank","stem":"当一个进程包含多个线程时，这些线程除各自私有少量资源以外，______所属进程的全部资源。","ref":"共享","explanation":"共享","blankCount":1,"blanks":[["共享"]],"explain":"考点3.3 线程的属性：同一个进程中的各个线程**共享**该进程的内存地址空间，除各自私有的寄存器、栈等少量现场资源外，**共享**所属进程的全部资源。"},{"id":64,"chapter":"第三章进程","type":"essay","stem":"简述线程与进程的关系。","ref":"（1）线程是进程中可独立执行的子任务；（2）一个进程中可以有一个或多个线程；（3）同一进程中的各线程共享分配给进程的主存空间；（4）进程是资源分配单位，线程是调度和执行单位；（5）一个进程内的线程共享分配给该进程的资源","explanation":"（1）线程是进程中可独立执行的子任务；（2）一个进程中可以有一个或多个线程；（3）同一进程中的各线程共享分配给进程的主存空间；（4）进程是资源分配单位，线程是调度和执行单位；（5）一个进程内的线程共享分配给该进程的资源。","points":["线程是进程中可独立执行的子任务，一个进程可有一个或多个线程","同一进程中的各线程共享分配给进程的主存空间和资源","进程是资源分配单位，线程是调度和执行单位"],"pointsMd":["线程是进程中可独立执行的**子任务**，一个进程可有**一个或多个**线程","同一进程中的各线程共享分配给进程的**主存空间**和资源","进程是**资源分配**单位，线程是**调度和执行**单位"],"explain":"考点3.3/3.4 线程与进程的关系：（1）线程是进程中可独立执行的**子任务**，是进程中的一个实体；（2）一个进程中可以有**一个或多个**线程；（3）同一进程中的各线程共享分配给进程的**主存空间**（内存地址空间）；（4）进程是**资源分配单位**，线程是**调度和执行单位**；（5）一个进程内的线程共享分配给该**进程的资源**。配套：引入线程的好处——创建/切换花费时间少、线程间通信无须调用内核、能充分利用处理器与外设的并行能力。"},{"id":65,"chapter":"第三章进程","type":"blank","stem":"线程的实现机制包括______、 ______和混合方式","ref":"用户级线程内核级线程","explanation":"用户级线程内核级线程","blankCount":2,"blanks":[["用户级线程"],["内核级线程"]],"unordered":true,"explain":"考点3.4 线程的实现：线程可分为三类——**用户级线程**、**内核级线程**和混合方式实现的线程。另注意：协程是运行在线程之上的轻量级线程。"},{"id":66,"chapter":"第三章进程","type":"blank","stem":"多线程应用程序用一组用户级程序库来编写，将所有线程映射到一个单独的内核级进程中其中最著名的是：______","ref":"Pthread（POSIX thread）库","explanation":"Pthread（POSIX thread）库","blankCount":1,"blanks":[["Pthread（POSIX thread）库","Pthread库","Pthread","POSIX thread"]],"explain":"考点3.4：用户级线程的实现是用一组用户级程序库把所有线程映射到一个单独的内核级进程中，其中最著名的是**Pthread（POSIX thread）库**。"},{"id":67,"chapter":"第四章进程","type":"blank","stem":"______的任务是控制、 协调进程对CPU的竞争，按照一定的调度算法，使某一就绪进程获得CPU的控制权，转换成运行状态。","ref":"进程调度","explanation":"进程调度","blankCount":1,"blanks":[["进程调度"]],"explain":"考点4.1 进程调度的基本概念：**进程调度**即处理机调度，**进程调度**程序是操作系统的真正核心，直接负责CPU的分配——控制协调进程对CPU的竞争，按算法使就绪进程转为运行状态。"},{"id":68,"chapter":"第四章进程","type":"blank","stem":"______和______是CPU主要的两级调度。","ref":"进程调度、作业调度","explanation":"进程调度、作业调度","blankCount":2,"blanks":[["进程调度"],["作业调度"]],"unordered":true,"explain":"考点4.1：**进程调度**和**作业调度**是CPU主要的两级调度：**作业调度**（长程）把外存作业调入内存，**进程调度**（短程）把CPU分给就绪进程。"},{"id":69,"chapter":"第四章进程","type":"essay","stem":"简述进程调度的主要功能。","ref":"①保存现场：记录系统中所有进程的执行状况；②挑选进程：根据一定的调度算法，从就绪队列中选出一个进程，准备把处理器分配给它；③恢复现场：为选中的进程恢复现场信息","explanation":"①保存现场：记录系统中所有进程的执行状况；②挑选进程：根据一定的调度算法，从就绪队列中选出一个进程，准备把处理器分配给它；③恢复现场：为选中的进程恢复现场信息。","points":["保存现场：记录系统中所有进程的执行状况","挑选进程：根据一定的调度算法，从就绪队列中选出进程，把处理器分配给它","恢复现场：为选中的进程恢复现场信息"],"pointsMd":["保存现场：记录系统中所有进程的**执行状况**","挑选进程：根据一定的调度算法，从**就绪队列**中选出进程，把处理器分配给它","恢复现场：为选中的进程恢复**现场信息**"],"explain":"考点4.1 进程调度的主要功能：①保存现场——记录系统中所有进程的执行状况；②挑选进程——根据一定的调度算法，从就绪队列中选出一个进程，准备把处理器分配给它；③恢复现场——为选中的进程恢复现场信息。记“**保存→挑选→恢复**”三步。"},{"id":70,"chapter":"第四章进程","type":"essay","stem":"简述在选择调度策略时应该考虑什么因素。","ref":"① 设计目标② 公平性③ 均衡性④ 统筹兼顾⑤ 优先级⑥ 开销","explanation":"① 设计目标② 公平性③ 均衡性④ 统筹兼顾⑤ 优先级⑥ 开销","points":["设计目标","统筹兼顾"],"pointsMd":["**设计目标**","**统筹兼顾**"],"explain":"考点4.2 调度策略的选择六因素：①**设计目标**；②**公平性**；③**均衡性**；④**统筹兼顾**；⑤**优先级**；⑥**开销**。先明确**设计目标**，再在公平与**开销**之间权衡。"},{"id":71,"chapter":"第四章进程","type":"blank","stem":"______能有效地降低作业的平均等待时间和提高系统的吞吐量，对长作业很不利，并且不能保证紧迫性作业会被及时处理。","ref":"短作业优先法","explanation":"短作业优先法","blankCount":1,"blanks":[["短作业优先法"]],"explain":"考点4.3 经典调度算法：最短作业优先调度（SJF）能有效降低作业**平均等待时间**、提高**吞吐量**，但**长作业**可能长期得不到调度（**饿死**），也不能保证紧迫性作业及时处理——题干描述的正是它的缺点。"},{"id":72,"chapter":"第四章进程","type":"blank","stem":"______主要用于分时系统中的进程调度。","ref":"时间片轮转法（Round-Robin，RR）","explanation":"时间片轮转法（Round-Robin，RR）","blankCount":1,"blanks":[["时间片轮转法（Round-Robin，RR）","时间片轮转法","Round-Robin","RR"]],"explain":"考点4.3：时间片轮转调度（**RR**）让每个进程依次执行一个时间片，响应及时、公平性好，主要用于分时系统中的进程调度。"},{"id":73,"chapter":"第四章进程","type":"essay","stem":"简述进程最短剩余时间优先调度算法的基本思路和实现方法？","ref":"最短进程优先算法的抢占式版本是最短剩余时间优先（ Shortest Remaining TimeNext，SRTN）算法。使用这个算法，调度程序总是选择其剩余运行时间最短的那个进程运行。当一个新的进程到达时，其整个时间同当前进程的剩余时间做比较。如果新的进程比当前运行进程需要更少的时间，当前进程就被挂起，而运行新的进程。 这种方式可以使新的短进程获得良好的服务","explanation":"最短进程优先算法的抢占式版本是最短剩余时间优先（ Shortest Remaining TimeNext，SRTN）算法。使用这个算法，调度程序总是选择其剩余运行时间最短的那个进程运行。当一个新的进程到达时，其整个时间同当前进程的剩余时间做比较。如果新的进程比当前运行进程需要更少的时间，当前进程就被挂起，而运行新的进程。 这种方式可以使新的短进程获得良好的服务。","points":["最短剩余时间优先SRTN，是最短进程优先算法的抢占式版本","调度程序总是选择其剩余运行时间最短的那个进程运行","新进程到达时做比较，需要更少的时间，当前进程就被挂起，运行新的进程"],"pointsMd":["**最短剩余时间优先**SRTN，是最短进程优先算法的**抢占式**版本","调度程序总是选择其**剩余运行时间最短**的那个进程运行","新进程到达时做比较，需要**更少的时间**，当前进程就**被挂起**，运行新的进程"],"explain":"考点4.3 最短剩余时间优先调度：最**短进程**优先算法的**抢占式版本**是**最短剩余时间优先**（SRTN）算法。使用这个算法，调度程序总是选择其**剩余运行时间最短**的那个进程运行；当一个新的进程到达时，其整个时间同当前进程的剩余时间做比较，如果新的进程比当前运行进程需要更少的时间，当前进程就**被挂起**，而运行新的进程。这种方式可以使新的**短进程**获得良好的服务。"},{"id":74,"chapter":"第四章进程","type":"blank","stem":"______的目标是保证每个进程享用CPU的时间完全一样，即如果系统里一共有n 个进程，则每个进程占用CPU的时间为______。","ref":"保证调度算法，1/n","explanation":"保证调度算法，1/n","blankCount":2,"blanks":[["保证调度算法"],["1/n"]],"explain":"考点4.4 其他调度算法：**保证调度算法**是一种完全不同的调度算法，它向用户做出明确的性能保证然后去实现——保证每个进程享用CPU的时间完全一样，n个进程各占**1/n**。"},{"id":75,"chapter":"第四章进程","type":"blank","stem":"______是一种概率调度算法。","ref":"彩票调度算法","explanation":"彩票调度算法。","blankCount":1,"blanks":[["彩票调度算法"]],"explain":"考点4.4：**彩票调度算法**是一种概率调度算法——按进程持有彩票的多少随机开奖决定下一个运行的进程。"},{"id":76,"chapter":"第四章进程","type":"blank","stem":"基于进程组的调度决策是非常具有吸引力的。该方法通常称作______。","ref":"公平共享调度（fair-share scheduling）","explanation":"公平共享调度（fair-share scheduling）。","blankCount":1,"blanks":[["公平共享调度（fair-share scheduling）","公平共享调度","fair-share scheduling"]],"explain":"考点4.4：基于进程组（如按用户分组）的调度决策非常具有吸引力，该方法通常称作**公平共享调度（fair-share scheduling）**，保证每组获得应有的CPU份额。"},{"id":77,"chapter":"第四章进程","type":"blank","stem":"BSD UNIX系统主要用于______环境中，调度算法设计成为交互用户提供好的响应时间，同时保证低优先级的后台作业不会饿死。","ref":"分时交互","explanation":"分时交互。","blankCount":1,"blanks":[["分时交互"]],"explain":"考点4.5：BSD UNIX系统主要用于**分时交互**环境，采用多级反馈队列法、在每个优先级队列中采用轮转方法——为交互用户提供好的响应时间，同时保证低优先级后台作业不会饿死。"},{"id":78,"chapter":"第四章进程","type":"blank","stem":"Linux系统的调度方式基本上采用“______”方式。","ref":"抢占式优先级","explanation":"抢占式优先级","blankCount":1,"blanks":[["抢占式优先级"]],"explain":"考点4.5：Linux系统的调度方式基本上采用“**抢占式优先级**”方式：高优先级进程一旦就绪，立即抢占当前运行的低优先级进程。"},{"id":79,"chapter":"第四章进程","type":"blank","stem":"Windows中的优先级被组织成两段：______和______。","ref":"实时，可变","explanation":"实时，可变","blankCount":2,"blanks":[["实时"],["可变"]],"unordered":true,"explain":"考点4.5：Windows中的优先级被组织成两段（两类）：**实时**和**可变**——**实时**段固定不变，**可变**段由系统依据运行情况动态调整。"},{"id":80,"chapter":"第四章进程","type":"blank","stem":"在任何情况下，都可以把系统看作是______结构。","ref":"多服务器排队","explanation":"多服务器排队","blankCount":1,"blanks":[["多服务器排队"]],"explain":"考点4.6：在排队论模型中，在任何情况下都可以把系统看作**多服务器排队**结构，用于对多道程序系统做性能分析。"},{"id":81,"chapter":"第四章进程","type":"blank","stem":"线程调度常用的方法有______，______，______，______。","ref":"加载共享，组调度，专用处理器分配，动态调度","explanation":"加载共享，组调度，专用处理器分配，动态调度","blankCount":4,"blanks":[["加载共享"],["组调度"],["专用处理器分配"],["动态调度"]],"unordered":true,"explain":"考点4.6 多处理器调度：线程调度常用的四种方法——**加载共享**、**组调度**、**专用处理器分配**、**动态调度**。其中**专用处理器分配**是**组调度**的一种极端形式（应用程序执行期间把一组处理器专门分配给它）。"},{"id":82,"chapter":"第四章进程","type":"essay","stem":"简述加载共享的缺点。","ref":"中心队列占据了必须互斥访问的存储器区域被抢占的线程可能不在同一个处理器上恢复执行, 如果一个程序的线程间需要高度的合作，所涉及的进程切换就会严重影响性能","explanation":"中心队列占据了必须互斥访问的存储器区域被抢占的线程可能不在同一个处理器上恢复执行, 如果一个程序的线程间需要高度的合作，所涉及的进程切换就会严重影响性能。","points":["中心队列占据了必须互斥访问的存储器区域","被抢占的线程可能不在同一个处理器上恢复执行","线程间需要高度合作时，进程切换会严重影响性能"],"pointsMd":["**中心队列**占据了必须互斥访问的存储器区域","被抢占的线程可能**不在同一个处理器**上恢复执行","线程间需要高度合作时，**进程切换**会严重影响性能"],"explain":"考点4.6 多处理器调度之加载共享的缺点：①**中心队列**占据了必须**互斥访问**的存储器区域（成为**瓶颈**）；②被抢占的线程可能**不在同一个处理器**上恢复执行；③如果一个程序的线程间需要高度的合作，所涉及的**进程切换**就会严重影响性能。"},{"id":83,"chapter":"第四章进程","type":"blank","stem":"为周期性任务解决多任务调度冲突的一个非常好的方法是______","ref":"速率单调调度RMS","explanation":"速率单调调度RMS","blankCount":1,"blanks":[["速率单调调度RMS"]],"explain":"考点4.7 实时调度算法：**静态表驱动调度**适用于周期性任务；速率单调调度（**RMS**）按任务周期长短定优先级——**周期越短**（速率越高）优先级越高，是解决周期性任务多任务调度冲突的好方法。"},{"id":84,"chapter":"第四章进程","type":"blank","stem":"______在任何基于优先级的可抢占的调度方案中都能发生的一种现象，但是它与实时调度的上下文关联特别大。","ref":"优先级逆转（priority inversion）","explanation":"优先级逆转（priority inversion）","blankCount":1,"blanks":[["优先级逆转（priority inversion）","优先级逆转","priority inversion"]],"explain":"考点4.7：**优先级反转**是一种在任何基于优先级的可抢占的调度方案中都能发生的现象——高优先级任务等待持有资源的低优先级任务，而后者又被**中优先级**任务抢占，它与实时调度的上下文关联特别大。"},{"id":85,"chapter":"第四章进程","type":"blank","stem":"______的基本思想是优先级较低的任务继承任何与它共享同一个资源的优先级较高的任务的优先级。","ref":"优先级继承协议","explanation":"优先级继承协议","blankCount":1,"blanks":[["优先级继承协议"]],"explain":"考点4.7：**优先级继承协议**的基本思想：优先级较低的任务继承任何与它共享同一个资源的优先级较高的任务的优先级，从而不被中优先级任务抢占，缓解优先级反转。"},{"id":86,"chapter":"第五章存储管理","type":"single","stem":"存储体系不包括（ ）","ref":"虚拟存储不是存储体系中的一部分","explanation":"虚拟存储不是存储体系中的一部分。","options":[{"key":"A","text":"寄存器"},{"key":"B","text":"内存"},{"key":"C","text":"外存"},{"key":"D","text":"虚拟存储"}],"answer":"D","explain":"虚拟存储不是存储体系中的一部分。"},{"id":87,"chapter":"第五章存储管理","type":"single","stem":"动态重定位中，若程序执行时，被改变了存储区域仍能正确执行，则称程序是（ ）","ref":"采用动态重定位的系统支持“程序浮动” ； 采用静态重定位的系统不支持“程序浮动”","explanation":"采用动态重定位的系统支持“程序浮动” ； 采用静态重定位的系统不支持“程序浮动” 。","options":[{"key":"A","text":"可浮动的"},{"key":"B","text":"可转换的"},{"key":"C","text":"可更改的"},{"key":"D","text":"可分配的"}],"answer":"A","explain":"采用动态重定位的系统支持“程序浮动” ； 采用静态重定位的系统不支持“程序浮动” 。"},{"id":88,"chapter":"第五章存储管理","type":"blank","stem":"两个或多个进程共用内存中相同区域是指______。","ref":"存储共享","explanation":"存储共享","blankCount":1,"blanks":[["存储共享"]],"explain":"考点5.1：内存（存储）共享是指两个或多个进程共用内存中**相同区域**，不仅能使多道程序动态共享内存、提高利用率，还能共享某区域的信息；共享内容包括**代码共享**和**数据共享**，**代码共享**要求必须是**纯代码**（运行中不会改变）。"},{"id":89,"chapter":"第五章存储管理","type":"blank","stem":"存储管理的主要任务包括内存的分配与回收、 内存扩充、 ______和______。","ref":"存储共享、存储保护","explanation":"存储共享、存储保护","blankCount":2,"blanks":[["存储共享"],["存储保护"]],"unordered":true,"explain":"考点1.3/5.1：存储管理的主要任务四项：内存的分配与回收、内存扩充、**存储共享**、**存储保护**。按“**分配回收**、**扩充**、**共享**、**保护**”记忆。"},{"id":90,"chapter":"第五章存储管理","type":"blank","stem":"在存储管理中，将绝对地址对应的存储空间称为 ______，将逻辑地址对应的存储空间称为______。","ref":"物理地址空间逻辑地址空间","explanation":"物理地址空间逻辑地址空间","blankCount":2,"blanks":[["物理地址空间"],["逻辑地址空间"]],"explain":"考点5.1：**地址重定位**是把逻辑**地址转换**成绝对地址的工作（又称**地址转换**、**地址映射**）。绝对地址对应的存储空间称为**物理地址空间**，逻辑地址对应的存储空间称为**逻辑地址空间**。"},{"id":91,"chapter":"第五章存储管理","type":"single","stem":"当接到内存申请时，查找分区说明表，找到能满足申请要求的最大的空闲区，这种算法被称为（ ）","ref":"当接到内存申请时，查找分区说明表，找到能满足申请要求的最大的空闲是最坏适应算法","explanation":"当接到内存申请时，查找分区说明表，找到能满足申请要求的最大的空闲是最坏适应算法。","options":[{"key":"A","text":"最优适应算法"},{"key":"B","text":"最新适应算法"},{"key":"C","text":"最先适应算法"},{"key":"D","text":"最坏适应算法"}],"answer":"D","explain":"当接到内存申请时，查找分区说明表，找到能满足申请要求的最大的空闲是最坏适应算法。"},{"id":92,"chapter":"第五章存储管理","type":"single","stem":"实现多道程序设计的一种简单易行的存储管理技术是（ ）","ref":"通过分区管理，内存真正成为了共享资源，提高了系统的吞吐量和缩短了周转时间。分区内存管理算法比较简单，实现起来比较容易，内存额外开销较少，内存保护措施简单。内存利用率，可变分区的内存利用率比固定分区高","explanation":"通过分区管理，内存真正成为了共享资源，提高了系统的吞吐量和缩短了周转时间。分区内存管理算法比较简单，实现起来比较容易，内存额外开销较少，内存保护措施简单。内存利用率，可变分区的内存利用率比固定分区高。","options":[{"key":"A","text":"分区管理"},{"key":"B","text":"虚拟存储技术"},{"key":"C","text":"覆盖技术"},{"key":"D","text":"交换技术"}],"answer":"A","explain":"通过分区管理，内存真正成为了共享资源，提高了系统的吞吐量和缩短了周转时间。分区内存管理算法比较简单，实现起来比较容易，内存额外开销较少，内存保护措施简单。内存利用率，可变分区的内存利用率比固定分区高。"},{"id":93,"chapter":"第五章存储管理","type":"blank","stem":"在可变分区存储管理方案中，解决碎片问题的一个有效办法是采用紧缩技术，通过移动内存中程序，把______的合并成一个连续的大空闲区置于内存的一端，把______的放在内存的另一端。","ref":"所有空闲碎片所有程序占用区","explanation":"所有空闲碎片所有程序占用区","blankCount":2,"blanks":[["所有空闲碎片"],["所有程序占用区"]],"explain":"考点5.2：紧缩技术（内存紧缩）——在适当时刻进行碎片整理，通过移动内存中的程序，把**所有空闲碎片**合并成一个连续的大空闲区，程序占用区集中到内存另一端，从而解决可变分区的碎片问题。"},{"id":94,"chapter":"第五章存储管理","type":"blank","stem":"解决外碎片问题的办法是在适当时刻进行碎片整理，通过移动内存中的程序，把所有空闲碎片合并成一个连续的大空闲区，这种方法称之为______","ref":"紧缩技术","explanation":"紧缩技术","blankCount":1,"blanks":[["紧缩技术"]],"explain":"考点5.2：解决外部碎片的办法=移动进程+合并空闲碎片成大连续区，这种方法称为“**内存紧缩**”（**紧缩技术**）。代价：需要移动大量信息，浪费处理器时间。"},{"id":95,"chapter":"第五章存储管理","type":"single","stem":"下列选项中，对于覆盖技术说法错误的是（ ）","ref":"覆盖技术不需要操作系统的特殊支持，可以完全由用户实现，即覆盖技术是用户程序自己附加的控制","explanation":"覆盖技术不需要操作系统的特殊支持，可以完全由用户实现，即覆盖技术是用户程序自己附加的控制","options":[{"key":"A","text":"覆盖技术需要来自操作系统的特殊支持"},{"key":"B","text":"覆盖技术是早期采用的简单的扩充内存的技术"},{"key":"C","text":"覆盖技术主要用于系统程序的内存管理上"},{"key":"D","text":"覆盖技术打破了需要将一个程序的全部信息装入内存后程序才能运行的限制"}],"answer":"A","explain":"覆盖技术不需要操作系统的特殊支持，可以完全由用户实现，即覆盖技术是用户程序自己附加的控制"},{"id":96,"chapter":"第五章存储管理","type":"blank","stem":"______是指一个程序的若干程序段，或几个程序的某些部分共享某一个存储空间。","ref":"覆盖技术","explanation":"覆盖技术","blankCount":1,"blanks":[["覆盖技术"]],"explain":"考点5.3 覆盖技术：指一个程序的若干程序段，或几个程序的某些部分共享某一个存储空间——把**不会同时执行**的程序段共享同一块内存区域，未执行的段先存磁盘，前段执行完后调入后续程序段**覆盖**前面的程序段。"},{"id":97,"chapter":"第五章存储管理","type":"blank","stem":"交换技术是进程在______与______之间的动态调度，是由操作系统控制的","ref":"内存,外存","explanation":"内存,外存","blankCount":2,"blanks":[["内存"],["外存"]],"unordered":true,"explain":"考点5.3：交换技术又称对换技术——当用户进程需要的**内存**总量超过实际**内存**时，在磁盘上保存**内存**放不下的进程，需要运行时再装入**内存**，即进程在**内存**与**外存**之间的动态调度，由操作系统控制。"},{"id":98,"chapter":"第五章存储管理","type":"essay","stem":"简述存储管理中交换技术的实现原理及主要作用？","ref":"交换技术又称对换技术。进程从内存移到磁盘，并再移回内存称为交换。交换技术是进程在内存与外存之间的动态调度，是由操作系统控制的。交换技术的目的是尽可能达到“足够快地交换进程，以使当处理器调度程序想重新调度处理器时，总有进程在内存中处于就绪（准备执行）状态”的理想状态，从而提高内存利用率","explanation":"交换技术又称对换技术。进程从内存移到磁盘，并再移回内存称为交换。交换技术是进程在内存与外存之间的动态调度，是由操作系统控制的。交换技术的目的是尽可能达到“足够快地交换进程，以使当处理器调度程序想重新调度处理器时，总有进程在内存中处于就绪（准备执行）状态”的理想状态，从而提高内存利用率。","points":["交换技术又称对换技术：进程从内存移到磁盘，并再移回内存","进程在内存与外存之间的动态调度，由操作系统控制","重新调度处理器时，总有进程在内存中处于就绪状态，从而提高内存利用率"],"pointsMd":["交换技术又称对换技术：进程从**内存移到磁盘**，并再移回内存","进程在内存与外存之间的**动态调度**，由操作系统控制","重新调度处理器时，总有进程在内存中处于**就绪状态**，从而提高内存**利用率**"],"explain":"考点5.3 交换技术：交换技术又称**对换技术**。在分时操作系统中，用户的进程需要的内存总量比系统中实际内存的总量要多，就需要在磁盘上保存那些在内存**放不下的进程**，在需要运行这些进程时再将它们装入内存——即进程在内存与外存之间的**动态调度**，由操作系统控制。实际使用时需考虑四个主要问题：**换出进程的选择**、交换时机的确定、交换空间的分配、换入进程换回内存时位置的确定。作用：支持多道程序与分时运行，相当于扩充内存。"},{"id":99,"chapter":"第五章存储管理","type":"single","stem":"采用页式存储管理的主要目的是提高（ ）","ref":"页式存储管理部件首先把内存分成大小相等的许多区，把每个区称为“物理页面”，物理页面是进行内存空间分配的物理单位。其目的就是为了提高内存的利用率","explanation":"页式存储管理部件首先把内存分成大小相等的许多区，把每个区称为“物理页面”，物理页面是进行内存空间分配的物理单位。其目的就是为了提高内存的利用率。","options":[{"key":"A","text":"内存的利用率"},{"key":"B","text":"程序并发度"},{"key":"C","text":"系统的吞吐量"},{"key":"D","text":"系统的可靠性"}],"answer":"A","explain":"页式存储管理部件首先把内存分成大小相等的许多区，把每个区称为“物理页面”，物理页面是进行内存空间分配的物理单位。其目的就是为了提高内存的利用率。"},{"id":100,"chapter":"第五章存储管理","type":"single","stem":"为避免页表占用较多存储空间的情况，大多数操作系统采用的进程页表是（ ）","ref":"大多数32位的操作系统中采用二级页表，即由页表页和页目录一起构成进程页表","explanation":"大多数32位的操作系统中采用二级页表，即由页表页和页目录一起构成进程页表","options":[{"key":"A","text":"一级页表"},{"key":"B","text":"二级页表"},{"key":"C","text":"反置页表"},{"key":"D","text":"链式页表"}],"answer":"B","explain":"大多数32位的操作系统中采用二级页表，即由页表页和页目录一起构成进程页表"},{"id":101,"chapter":"第五章存储管理","type":"single","stem":"页式存储管理器中的快表（TLB）一般存放在（ ）","ref":"为了提高存取速度，有两种方法： 在地址映射机制中增加一组高速寄存器保存页表。需要硬件支持， 经济上不可行。 在地址映射机制中增加一个小容量的联想寄存器（相联存储器），它由高速缓冲存储器组成","explanation":"为了提高存取速度，有两种方法： 在地址映射机制中增加一组高速寄存器保存页表。需要硬件支持， 经济上不可行。 在地址映射机制中增加一个小容量的联想寄存器（相联存储器），它由高速缓冲存储器组成。","options":[{"key":"A","text":"内存"},{"key":"B","text":"外存"},{"key":"C","text":"寄存器"},{"key":"D","text":"高速缓冲存储器"}],"answer":"D","explain":"为了提高存取速度，有两种方法： 在地址映射机制中增加一组高速寄存器保存页表。需要硬件支持， 经济上不可行。 在地址映射机制中增加一个小容量的联想寄存器（相联存储器），它由高速缓冲存储器组成。"},{"id":102,"chapter":"第五章存储管理","type":"blank","stem":"页式存储管理要求对程序中的逻辑地址空间进行分页，于是系统提供给编程使用的逻辑地址可由两部分组成：______和______","ref":"虚拟页号、页内地址","explanation":"虚拟页号、页内地址","blankCount":2,"blanks":[["虚拟页号"],["页内地址"]],"unordered":true,"explain":"考点5.4 虚拟页式存储管理：页式管理要求对逻辑地址空间分页，于是逻辑地址由两部分组成——**虚拟页号**+**页内地址**（偏移量），硬件按位数自动拆分，页号经查页表得到物理页面号。"},{"id":103,"chapter":"第五章存储管理","type":"essay","stem":"简述虚拟页式存储管理的优缺点？","ref":"优点：由于它不要求进程的程序段和数据在内存中连续存放，从而有效地解决了碎片问题。这既提高了内存的利用率，又有利于组织多道程序执行。缺点：存在页面空间的浪费问题。这是由于各种程序代码的长度是各不相同的，但页面的大小是固定的，所以在每个程序的最后一页内总有一部分空间得不到利用。如果页面较大，则由此引起的存储空间的损失仍然较大","explanation":"优点：由于它不要求进程的程序段和数据在内存中连续存放，从而有效地解决了碎片问题。这既提高了内存的利用率，又有利于组织多道程序执行。缺点：存在页面空间的浪费问题。这是由于各种程序代码的长度是各不相同的，但页面的大小是固定的，所以在每个程序的最后一页内总有一部分空间得不到利用。如果页面较大，则由此引起的存储空间的损失仍然较大。","points":["不要求进程的程序段和数据，在内存中连续存放，解决了碎片问题","提高了内存的利用率，又有利于组织多道程序执行","页面的大小是固定的，每个程序的最后一页内，总有一部分空间得不到利用","页面较大，引起的存储空间的损失仍然较大"],"pointsMd":["不要求进程的程序段和数据，在内存中**连续存放**，解决了**碎片**问题","提高了内存的利用率，又有利于组织**多道程序**执行","页面的大小是固定的，每个程序的**最后一页**内，总有一部分空间**得不到利用**","页面较大，引起的**存储空间的损失**仍然较大"],"explain":"考点5.4 虚拟页式存储管理的优缺点：主要优点——不要求进程的程序段和数据在内存中连续存放，因此有效地解决了（外部）**碎片**问题，既提高了内存的利用率，又有利于组织多道程序执行。主要缺点——存在页面空间的浪费：各种程序代码的长度各不相同，但页面的大小固定，每个程序的**最后一页**内总会有一部分空间得不到利用（内**碎片**）；如果页面较大，由此引起的**存储空间损失**仍然较大。"},{"id":104,"chapter":"第六章文件系统","type":"single","stem":"操作系统中，统一管理信息资源的软件是（ ）","ref":"文件系统是操作系统中统一管理信息资源的一种软件","explanation":"文件系统是操作系统中统一管理信息资源的一种软件","options":[{"key":"A","text":"存储系统"},{"key":"B","text":"文件系统"},{"key":"C","text":"设备系统"},{"key":"D","text":"进程系统"}],"answer":"B","explain":"文件系统是操作系统中统一管理信息资源的一种软件"},{"id":105,"chapter":"第六章文件系统","type":"single","stem":"用磁带作为文件存储介质时，文件只能组织成（ ）","ref":"磁带是最早使用的磁记录存储介质。显然，磁带是一种顺序存取设备，因为在磁带上，只有在前面的物理块被访问之后，才能存取后续的物理块","explanation":"磁带是最早使用的磁记录存储介质。显然，磁带是一种顺序存取设备，因为在磁带上，只有在前面的物理块被访问之后，才能存取后续的物理块。","options":[{"key":"A","text":"链接文件"},{"key":"B","text":"顺序文件"},{"key":"C","text":"索引文件"},{"key":"D","text":"目录文件"}],"answer":"B","explain":"磁带是最早使用的磁记录存储介质。显然，磁带是一种顺序存取设备，因为在磁带上，只有在前面的物理块被访问之后，才能存取后续的物理块。"},{"id":106,"chapter":"第六章文件系统","type":"single","stem":"有序字符的集合称为（ ）","ref":"流式文件是有序字符的集合","explanation":"流式文件是有序字符的集合","options":[{"key":"A","text":"流式文件"},{"key":"B","text":"记录式文件"},{"key":"C","text":"不记录式文件"},{"key":"D","text":"定式文件"}],"answer":"A","explain":"流式文件是有序字符的集合"},{"id":107,"chapter":"第六章文件系统","type":"single","stem":"常用的文件物理结构不包括（ ）","ref":"常用的文件物理结构包括：索引结构、链接结构、顺序结构","explanation":"常用的文件物理结构包括：索引结构、链接结构、顺序结构。","options":[{"key":"A","text":"索引结构"},{"key":"B","text":"链接结构"},{"key":"C","text":"空间结构"},{"key":"D","text":"顺序结构"}],"answer":"C","explain":"常用的文件物理结构包括：索引结构、链接结构、顺序结构。"},{"id":108,"chapter":"第六章文件系统","type":"blank","stem":"把文件按组织形式进行分类，可以分为普通文件、 ______和______等三类。","ref":"目录文件特殊文件","explanation":"目录文件特殊文件","blankCount":2,"blanks":[["目录文件"],["特殊文件"]],"unordered":true,"explain":"考点6.1：按文件的组织形式可把文件分为普通文件、**目录文件**和**特殊文件**三类。注意与“**按用途分**”区分：系统文件、库函数文件、用户文件（押题第109题），两种分类标准别混淆。"},{"id":109,"chapter":"第六章文件系统","type":"blank","stem":"把文件按文件的用途进行分类，可以分为系统文件、 ______和______等三类。","ref":"库函数文件用户文件","explanation":"库函数文件用户文件","blankCount":2,"blanks":[["库函数文件"],["用户文件"]],"unordered":true,"explain":"考点6.1：按文件的用途可把文件分为系统文件、**库函数文件**和**用户文件**三类。"},{"id":110,"chapter":"第六章文件系统","type":"blank","stem":"文件常用的存取方法有：______和______","ref":"顺序存取和随机存取","explanation":"顺序存取和随机存取","blankCount":2,"blanks":[["顺序存取"],["随机存取"]],"unordered":true,"explain":"考点6.1：文件常用的存取方法有两种：**顺序存取**（按记录次序依次读写）和**随机存取**（直接跳到任意记录）。"},{"id":111,"chapter":"第六章文件系统","type":"essay","stem":"简述文件系统的功能。","ref":"（1）统一管理文件的存储空间，实施存储空间的分配与回收（2）实现文件从名字到外存地址空间的映射即实现文件的按名存取（3）实现文件信息的共享，并提供文件的保护措施（4）向用户提供一个方便使用的接口（5）系统维护及向用户提供有关信息（6）保持文件系统的执行效率文件系统在操作系统接口中占的比例最大（7）提供I/O的统一接口","explanation":"（1）统一管理文件的存储空间，实施存储空间的分配与回收（2）实现文件从名字到外存地址空间的映射即实现文件的按名存取（3）实现文件信息的共享，并提供文件的保护措施（4）向用户提供一个方便使用的接口（5）系统维护及向用户提供有关信息（6）保持文件系统的执行效率文件系统在操作系统接口中占的比例最大（7）提供I/O的统一接口","points":["统一管理文件的存储空间，实施存储空间的分配与回收","实现名字到外存地址空间的映射，按名存取","实现文件信息的共享，提供文件的保护措施","向用户提供一个方便使用的接口","系统维护及向用户提供有关信息","保持文件系统的执行效率","提供I/O的统一接口"],"pointsMd":["统一管理文件的存储空间，实施存储空间的**分配与回收**","实现名字到外存地址空间的映射，**按名存取**","实现文件信息的共享，提供文件的**保护措施**","向用户提供一个方便使用的**接口**","**系统维护**及向用户提供有关信息","保持文件系统的**执行效率**","提供**I/O**的统一接口"],"explain":"考点6.1 文件系统的功能：（1）统一管理文件的存储空间，实施存储空间的**分配与回收**；（2）实现文件从名字到外存地址空间的映射，即**按名存取**，以对用户**透明**的方式管理文件名；（3）实现文件信息的**共享**，并提供文件的**保护措施**；（4）向用户提供一个方便使用的**接口**（操作命令、信息存取加工等）；（5）**系统维护**及向用户提供有关信息。押题答案的**五点**与考点前五条对应。"},{"id":112,"chapter":"第六章文件系统","type":"blank","stem":"采用______的物理结构，有利于文件动态扩充，解决了存储的碎片问题，但是不合适随机存取。","ref":"链接结构","explanation":"链接结构","blankCount":1,"blanks":[["链接结构"]],"explain":"考点6.2 文件的物理结构三种：顺序（连续）结构、**链接结构**、索引结构。**链接结构**为每个文件构造所用磁盘块的链表，逻辑上连续的文件分散存放在不连续的物理块中——无碎片、利于动态扩充，但随机存取须顺链遍历。"},{"id":113,"chapter":"第六章文件系统","type":"essay","stem":"什么是逻辑文件？什么是物理文件？简述逻辑文件的几种形式。","ref":"用户组织的文件称为逻辑文件；存放在存储介质上的文件称为物理文件；流式文件是由一串顺序的字符流组成的；记录式文件是由若干逻辑记录组成的","explanation":"用户组织的文件称为逻辑文件；存放在存储介质上的文件称为物理文件；流式文件是由一串顺序的字符流组成的；记录式文件是由若干逻辑记录组成的。","points":["逻辑文件：用户组织的文件","物理文件：存放在存储介质上的文件","流式文件：由一串顺序的字符流组成","记录式文件：由若干逻辑记录组成"],"pointsMd":["逻辑文件：**用户组织**的文件","物理文件：存放在**存储介质**上的文件","流式文件：由一串顺序的**字符流**组成","记录式文件：由若干**逻辑记录**组成"],"explain":"考点6.2 文件的逻辑结构和物理结构：用户组织的（用户所看到的组织形式）文件称为**逻辑文件**，存放在存储介质上的文件称为**物理文件**。**逻辑文件**三类：无结构的字符流式文件、有结构的定长记录文件和不定长记录文件构成的记录树（后两者统称记录式文件）。物理结构三种：顺序（连续）结构、链接结构、索引结构。"},{"id":114,"chapter":"第六章文件系统","type":"blank","stem":"为了实现“按名存取”，操作系统给每个文件都设置了一个描述性数据结构______ 。它是文件存在的标准，把所有文件的描述性数据结构组织起来，就构成了______ 。","ref":"文件控制块文件目录","explanation":"文件控制块文件目录","blankCount":2,"blanks":[["文件控制块"],["文件目录"]],"explain":"考点6.3 文件目录：为了管理大量文件，为每个文件设置一个描述性数据结构——**文件控制块**（FCB），它是文件存在的标志；把所有文件的FCB有机组织起来构成的有序集合称为**文件目录**，从而实现“**按名存取**”。"},{"id":115,"chapter":"第六章文件系统","type":"blank","stem":"把二级目录的层次关系加以推广，就形成了多级目录，又称______","ref":"树型目录结构","explanation":"树型目录结构","blankCount":1,"blanks":[["树型目录结构"]],"explain":"考点6.3：文件目录结构一般设计成**一级**（单级）、**二级**和**多级**目录结构；把**二级**目录的层次关系加以推广，就形成了**多级**目录，又称**树型目录结构**（以根目录为顶）。"},{"id":116,"chapter":"第六章文件系统","type":"blank","stem":"用户在访问文件时，需要进行目录检索，这时用户给出文件名，系统按名寻找目录项。有两种根据路径名检索的方法：一种是______，另一种是______","ref":"全路径名、相对路径","explanation":"全路径名、相对路径","blankCount":2,"blanks":[["全路径名"],["相对路径"]],"unordered":true,"explain":"考点6.3：目录检索时用户给出文件名，系统按名寻找**目录项**。按路径名检索的两种写法：**全路径名**（从根目录写起，路径唯一）和**相对路径**（从当前工作目录写起，简短方便）。"},{"id":117,"chapter":"第六章文件系统","type":"blank","stem":"______的空间容量比较大，对文件删除之后而不再使用的空间，必须加以回收，然后在建立文件等操作中重新利用。","ref":"外存储设备.","explanation":"外存储设备.","blankCount":1,"blanks":[["外存储设备."]],"explain":"考点6.1：**外存储设备**与内存相比有容量大、**非易失**、速度较慢、成本较低等特点。文件本体存放在**外存储设备**上，文件删除后不再使用的空间必须**回收**，在建立文件等操作中重新利用。"},{"id":118,"chapter":"第六章文件系统","type":"blank","stem":"为了进行存储空间的分配与回收，在外存储设备上设置有______，该表动态跟踪该外存储设备上所有还没有分配给任何文件的空闲块的数目和块号。","ref":"空闲空间登记表","explanation":"空闲空间登记表","blankCount":1,"blanks":[["空闲空间登记表"]],"explain":"考点6.4 文件存储空间管理：**空闲块表**是专门为空闲块建立的一张表，记录外存储设备全部空闲的物理块（包括第一个空闲块号和空闲块个数），**动态跟踪**空闲空间。"},{"id":119,"chapter":"第六章文件系统","type":"blank","stem":"磁盘空间的分配与回收算法有______、 ______、 ______。","ref":"位示图、空闲块表、空闲块链表","explanation":"位示图、空闲块表、空闲块链表","blankCount":3,"blanks":[["位示图"],["空闲块表"],["空闲块链表"]],"unordered":true,"explain":"考点6.4：磁盘空间的分配与回收三种算法——**位示图**（用一串二进制位的值反映磁盘空间分配使用情况）、**空闲块表**、**空闲块链表**（所有空闲块连成链表，首指针+块内后继指针）。"},{"id":120,"chapter":"第六章文件系统","type":"single","stem":"用户申请打开一个文件时，系统要在内存中为该用户保存一些必要的信息，这些信息以表格栏目中内容的形式出现，被称为（ ）","ref":"当用户申请打开一个文件时，系统要在内存中为该用户保存一些必要的信息，这些信息以表格栏目中内容的形式出现，被称为表目","explanation":"当用户申请打开一个文件时，系统要在内存中为该用户保存一些必要的信息，这些信息以表格栏目中内容的形式出现，被称为表目。","options":[{"key":"A","text":"目录项"},{"key":"B","text":"表目"},{"key":"C","text":"口令"},{"key":"D","text":"磁盘"}],"answer":"B","explain":"当用户申请打开一个文件时，系统要在内存中为该用户保存一些必要的信息，这些信息以表格栏目中内容的形式出现，被称为表目。"},{"id":121,"chapter":"第六章文件系统","type":"blank","stem":"系统打开文件表专门用于保存已打开文件的文件控制块，通常放在内存。该表格中还保存了______ 、 ______ 等信息。","ref":"共享计数修改标志","explanation":"共享计数修改标志","blankCount":2,"blanks":[["共享计数"],["修改标志"]],"unordered":true,"explain":"考点6.5 实现文件系统的表目：内存中的重要表目有**系统打开文件表**、**用户打开文件表**。**系统打开文件表**保存已打开文件的FCB，还保存**共享计数**（几个进程打开同一文件）和**修改标志**（FCB或i结点内容是否被改过）。"},{"id":122,"chapter":"第六章文件系统","type":"blank","stem":"共享计数标出有几个进程打开同一个文件；______是指文件控制块或i结点的内容是否被修改过，如果修改过，则关闭文件时要将______写回磁盘。","ref":"修改标志、文件控制块","explanation":"修改标志、文件控制块。","blankCount":2,"blanks":[["修改标志"],["文件控制块"]],"explain":"考点6.5：**修改标志**指**文件控制块**或i结点的内容是否被修改过；若修改过，则关闭文件时要将**文件控制块**写回磁盘，保证外存信息与内存一致。"},{"id":123,"chapter":"第六章文件系统","type":"blank","stem":"关闭文件系统调用的一般格式______ 。","ref":"close（文件名）","explanation":"close（文件名）","blankCount":1,"blanks":[["close（文件名）","close","文件名"]],"explain":"考点6.6 典型的文件操作七种：建立、打开、读、写、关闭、删除、**指针定位**。关闭文件调用的一般格式为**close（文件名）**，关闭后共享计数减一。"},{"id":124,"chapter":"第六章文件系统","type":"blank","stem":"UNIX的目录操作中删除目录项的操作是______ 。","ref":"unlink","explanation":"unlink","blankCount":1,"blanks":[["unlink"]],"explain":"考点6.6 UNIX目录操作：link建立新的目录项，**unlink**删除目录项；**链接计数**减为0时文件的物理块才被真正回收。"},{"id":125,"chapter":"第六章文件系统","type":"blank","stem":"用户首先调用文件系统的“______”操作，在请求调用该操作时，提供所要创建的文件的文件名及若干参数：用户名、 文件名、 存取方式、 存储设备类型、 记录格式、 记录长度，等等","ref":"建立文件","explanation":"建立文件","blankCount":1,"blanks":[["建立文件"]],"explain":"考点6.6：**建立文件**的具体步骤：①检查参数的合法性（文件名是否符合命名规则）→②检查同一目录下有无重名文件→③目录中有无空闲位置（有些系统同时申请数据块空间）→④填写目录项内容（文件名、用户名、存取权限、长度置0、首地址等）→⑤返回。"},{"id":126,"chapter":"第六章文件系统","type":"blank","stem":"读文件系统调用的一般格式为：______","ref":"read（文件名，（文件内位置）","explanation":"read（文件名，（文件内位置）","blankCount":1,"blanks":[["read（文件名，（文件内位置）","read","文件名","文件内位置"]],"explain":"考点6.6：读文件调用的一般格式为**read（文件名，（文件内位置）**，缓冲区，长度），从文件内指定位置读出指定长度的内容到缓冲区。"},{"id":127,"chapter":"第六章文件系统","type":"single","stem":"把若干个逻辑记录合成一组，存入一个物理块的工作称为（ ）","ref":"把若干个逻辑记录合成一组存放一物理块的工作称“记录的成组”，每块中的逻辑记录个数称“块因子”","explanation":"把若干个逻辑记录合成一组存放一物理块的工作称“记录的成组”，每块中的逻辑记录个数称“块因子”","options":[{"key":"A","text":"记录的分解"},{"key":"B","text":"块因子"},{"key":"C","text":"记录的成组"},{"key":"D","text":"记录的分散"}],"answer":"C","explain":"考点6.7：记录的**成组**和**分解**技术是磁盘高速缓存的一种应用：**成组**把若干逻辑记录拼成一个**物理块**，减少**启动设备的次数**；**分解**按需从块中取出记录，提高**存储空间利用率**。"},{"id":128,"chapter":"第六章文件系统","type":"essay","stem":"假定某系统中，磁带的记录密度为每英寸1200个字符，每个逻辑记录长为200个字符，块与块之间的间隙为0. 5英寸。请问，为了使磁带空间利用率达到70％，采用记录成组操作时的块因子应为多少？","ref":"设块因子为x。每条记录所占磁带空间为：200/1200=1/6英寸则（x*1/6）/ （x*1/6+0.5）=0.7解方程可得x=7，所以成组操作时，块因子是7","explanation":"设块因子为x。每条记录所占磁带空间为：200/1200=1/6英寸则（x*1/6）/ （x*1/6+0.5）=0.7解方程可得x=7，所以成组操作时，块因子是7。","points":["每条记录所占磁带空间为1/6英寸，设块因子为x","（x*1/6）/（x*1/6+0.5）=0.7","解方程可得x=7，块因子是7"],"pointsMd":["每条记录所占磁带空间为1/6英寸，设**块因子**为x","**（x*1/6）/（x*1/6+0.5）=0.7**","解方程可得**x=7**，块因子是7"],"explain":"成组因子计算：记录密度1200字符/英寸，每条逻辑记录200字符占200/1200=1/6英寸，块与块之间间隙0.5英寸。设**块因子**为x，则有效空间占比 (x/6)/(x/6+0.5)=0.7，解方程得x=7，所以成组操作时**块因子**是7。方法：设未知数→列占比方程→求解。"},{"id":129,"chapter":"第六章文件系统","type":"blank","stem":"记录的成组和分解技术是磁盘高速缓存的一种应用，虽然需要代价，但是具有提高______和减少______的优点。","ref":"存储空间利用率、 启动设备次数","explanation":"存储空间利用率、 启动设备次数","blankCount":2,"blanks":[["存储空间利用率"],["启动设备次数"]],"explain":"考点6.7：记录的成组和分解技术是磁盘高速缓存的一种应用，虽然需要代价，但具有提高**存储空间利用率**和减少**启动设备次数**的优点。"},{"id":130,"chapter":"第六章文件系统","type":"blank","stem":"用来解决磁盘速度慢、 出现故障的技术是______ 。","ref":"RAID技术","explanation":"RAID技术","blankCount":1,"blanks":[["RAID技术"]],"explain":"考点6.2：**RAID**（独立磁盘冗余阵列）技术用多盘并行工作提升速度、用冗余信息提供容错，是用来解决磁盘速度慢、出现故障的技术。"},{"id":131,"chapter":"第六章文件系统","type":"blank","stem":"RAID2和RAID3以______ 或______ 作为并行单位。","ref":"位、字节","explanation":"位、字节","blankCount":2,"blanks":[["位"],["字节"]],"unordered":true,"explain":"考点6.2：RAID2和RAID3以位或**字节**作为并行交叉单位，用极小的传输粒度让所有成员盘同时参与一次访问，获得很高传输率。"},{"id":132,"chapter":"第六章文件系统","type":"blank","stem":"规定用户使用文件的权限的方法有两种：______ 和______ 。","ref":"树形目录结构 、存取控制表","explanation":"树形目录结构 、存取控制表","blankCount":2,"blanks":[["树形目录结构"],["存取控制表"]],"unordered":true,"explain":"考点6.8 文件保护：规定用户使用文件的权限的方法有两种——（1）采用**树形目录结构**（从结构上隔离）；（2）**存取控制表**（按用户登记允许的操作）。"},{"id":133,"chapter":"第六章文件系统","type":"blank","stem":"UNIX的文件使用权限管理方案中，对文件存取权限的设置方法：______ 和______ 。","ref":"存取控制矩阵 、二级存取控制","explanation":"存取控制矩阵 、二级存取控制","blankCount":2,"blanks":[["存取控制矩阵"],["二级存取控制"]],"unordered":true,"explain":"考点6.8：UNIX的文件使用权限管理方案中，对文件存取权限的设置方法：**存取控制矩阵**（用户类×权限位）和**二级存取控制**（简化为所有者/组/其他三类对象的rwx权限）。"},{"id":134,"chapter":"第六章文件系统","type":"blank","stem":"______ 是指一个文件可以允许多个用户共同使用。","ref":"文件共享","explanation":"文件共享","blankCount":1,"blanks":[["文件共享"]],"explain":"考点6.8 文件共享：一个文件可以允许**多个用户**共同使用。好处：节省存储空间、免除系统复制文件的工作、减少用户重复性劳动、减少实际输入输出文件的次数，还可实现进程间的相互通信。"},{"id":135,"chapter":"第六章文件系统","type":"essay","stem":"简述UNIX的目录文件的存取权限及其含义。","ref":"读：允许读该目录（1分）写：允许修改目录内容（1分）执行：允许搜索该目录（2分）","explanation":"答：读：允许读该目录（1分）写：允许修改目录内容（1分）执行：允许搜索该目录（2分）","points":["读：允许读该目录","写：允许修改目录内容","执行：允许搜索该目录"],"pointsMd":["**读**：允许**读**该目录","写：允许**修改目录内容**","执行：允许**搜索该目录**"],"explain":"考点6.8 文件保护/UNIX权限：目录文件的三种存取权限及含义——读（r）：允许读该目录（列出目录项）；写（w）：允许修改目录内容（增删目录项）；执行（x）：允许搜索该目录（沿路径访问目录下文件）。对目录而言**执行权限**是能否访问其下文件的关键。"},{"id":136,"chapter":"第七章设备管理","type":"single","stem":"下列哪项不是按设备的使用特性分类的I/O设备（ ）。","ref":"按设备的使用特性分类：（1）输入设备（2）输出设备（3）交互式设备（4）存储设备等","explanation":"按设备的使用特性分类：（1）输入设备（2）输出设备（3）交互式设备（4）存储设备等。","options":[{"key":"A","text":"输入设备"},{"key":"B","text":"输出设备"},{"key":"C","text":"交互式设备"},{"key":"D","text":"独占式设备"}],"answer":"D","explain":"按设备的使用特性分类：（1）输入设备（2）输出设备（3）交互式设备（4）存储设备等。"},{"id":137,"chapter":"第七章设备管理","type":"single","stem":"计算机用以“感受”或“接触”外部信息的设备是（ ）","ref":"输入设备计算机用以“感受”或“接触”外部信息的设备","explanation":"输入设备计算机用以“感受”或“接触”外部信息的设备。","options":[{"key":"A","text":"输出设备"},{"key":"B","text":"输入设备"},{"key":"C","text":"交互式设备"},{"key":"D","text":"存储设备"}],"answer":"B","explain":"输入设备计算机用以“感受”或“接触”外部信息的设备。"},{"id":138,"chapter":"第七章设备管理","type":"single","stem":"操作系统底层中唯一知道各种输入输出设备控制器细节及其用途的部分是（ ）","ref":"设备驱动程序：最突出的特点是它与I/O设备的硬件结构密切联系。设备驱动程序是操作系统底层中唯一知道各种输入输出设备的控制器细节以及其用途的部分","explanation":"设备驱动程序：最突出的特点是它与I/O设备的硬件结构密切联系。设备驱动程序是操作系统底层中唯一知道各种输入输出设备的控制器细节以及其用途的部分。","options":[{"key":"A","text":"过程控制器"},{"key":"B","text":"通信控制器"},{"key":"C","text":"中断处理程序"},{"key":"D","text":"设备驱动程序"}],"answer":"D","explain":"设备驱动程序：最突出的特点是它与I/O设备的硬件结构密切联系。设备驱动程序是操作系统底层中唯一知道各种输入输出设备的控制器细节以及其用途的部分。"},{"id":139,"chapter":"第七章设备管理","type":"single","stem":"设计I／0软件的一个最关键的目标是（ ）","ref":"设计I/O软件的一个最关键的目标是设备独立性（Device ndependence），除了直接与设备打交道的底层软件之外，其他部分的软件并不依赖于硬件","explanation":"设计I/O软件的一个最关键的目标是设备独立性（Device ndependence），除了直接与设备打交道的底层软件之外，其他部分的软件并不依赖于硬件。","options":[{"key":"A","text":"按名存取"},{"key":"B","text":"设备独立性"},{"key":"C","text":"便于动态重定位"},{"key":"D","text":"提高系统吞吐率"}],"answer":"B","explain":"设计I/O软件的一个最关键的目标是设备独立性（Device ndependence），除了直接与设备打交道的底层软件之外，其他部分的软件并不依赖于硬件。"},{"id":140,"chapter":"第七章设备管理","type":"blank","stem":"键盘、 终端、 打印机等以______ 为单位组织和处理信息的设备。","ref":"字符","explanation":"字符","blankCount":1,"blanks":[["字符"]],"explain":"考点7.1 输入输出设备的分类：若以系统中信息组织方式来划分，可把I/O设备划分为**字符**设备和块设备——键盘、终端、打印机等以**字符**为单位组织和处理信息，属于**字符**设备。"},{"id":141,"chapter":"第七章设备管理","type":"blank","stem":"以信息块为单位组织和处理信息的设备被称为______ 能够随时读写设备中的任何一块存储块如磁盘、 磁带等","ref":"块设备","explanation":"块设备","blankCount":1,"blanks":[["块设备"]],"explain":"考点7.1：以信息块为单位组织和处理信息的设备称为**块设备**，能够随时读写设备中的任何一块存储块，如磁盘、磁带等。"},{"id":142,"chapter":"第七章设备管理","type":"blank","stem":"______ 是计算机用以产生普通人可感知的信息或输出用以“影响”或“控制”其他外部装置的设备，如打印机、 显示器","ref":"输出设备","explanation":"输出设备","blankCount":1,"blanks":[["输出设备"]],"explain":"考点7.1：按设备的使用特性分类，输入**输出设备**可分为输入设备、**输出设备**、交互式设备、存储设备等。**输出设备**是计算机用以产生普通人可感知的信息或输出用以“**影响**/**控制**”其他外部装置的设备，如打印机、显示器。"},{"id":143,"chapter":"第七章设备管理","type":"blank","stem":"从硬件的角度看，I/O硬件由______和______两部分组成","ref":"物理设备，电子部件","explanation":"物理设备，电子部件","blankCount":2,"blanks":[["物理设备"],["电子部件"]],"unordered":true,"explain":"考点7.2：从硬件的角度看，设备（I/O硬件）由**物理设备**和**电子部件**两部分组成。**物理设备**是达成设备功能的物质基础，对操作系统而言更注重的是其**电子部件**的控制方式。"},{"id":144,"chapter":"第七章设备管理","type":"blank","stem":"在典型的计算机系统硬件结构中，CPU与内存在最里层，通过总线与第二层的______部件相连，第三层是______，最外层是外围设备。","ref":"适配器（接口） 、各种外围设备控制器","explanation":"适配器（接口） 、各种外围设备控制器","blankCount":2,"blanks":[["适配器（接口）","适配器"],["各种外围设备控制器"]],"explain":"考点7.2 硬件层次：CPU与内存在最里层，通过总线与第二层的**适配器（接口）**部件相连，第三层是**各种外围设备控制器**，最外层是外围设备。"},{"id":145,"chapter":"第七章设备管理","type":"blank","stem":"为了使处理器能够访问设备控制器中的寄存器，须为每个寄存器分配唯一的地址，该地址称为：______或______ 。","ref":"I/O端口地址、I/O端口号","explanation":"I/O端口地址、I/O端口号","blankCount":2,"blanks":[["I/O端口地址"],["I/O端口号"]],"unordered":true,"explain":"考点7.2：为了使处理器能够访问设备控制器中的寄存器，须为每个寄存器分配唯一的地址，该地址称为**I/O端口地址**或**I/O端口号**。"},{"id":146,"chapter":"第七章设备管理","type":"blank","stem":"从功能上看， ______是I/O软件的主要部分；从代码量上看， ______是I/O软件的主要部分。","ref":"设备独立层 、设备驱动层","explanation":"设备独立层 、设备驱动层","blankCount":2,"blanks":[["设备独立层"],["设备驱动层"]],"explain":"考点7.2：一般的I/O软件结构分为四层：中断处理层、**设备驱动层**、**设备独立层**和用户层。从功能上来看，**设备独立层**是I/O软件的主要部分（向上提供统一接口）；从代码量上来看，**设备驱动层**是I/O软件的主要部分（每种设备都要实现）。"},{"id":147,"chapter":"第七章设备管理","type":"blank","stem":"对于字符设备当用户进程把数据写到设备的速度快于系统输出数据的速度时，必须使用______ 。","ref":"缓冲","explanation":"缓冲","blankCount":1,"blanks":[["缓冲"]],"explain":"考点2.5/7.6：**缓冲**技术一般在三种情况下采用（处理器与内存之间、处理器与外部设备之间、设备与设备之间通信），都是为了解决部件之间速度不匹配的问题。字符设备输出慢于进程写入速度时，必须使用**缓冲**。"},{"id":148,"chapter":"第七章设备管理","type":"single","stem":"I／0设备控制方式中，由用户进程直接控制处理器与外围设备之间进行信息传送的方式（ ）","ref":"程序控制方式也称为PIO（Programmed I/O，程控I/O）方式，是指由用户进程直接控制处理器或内存和外围设备之间进行信息传送的方式","explanation":"程序控制方式也称为PIO（Programmed I/O，程控I/O）方式，是指由用户进程直接控制处理器或内存和外围设备之间进行信息传送的方式。","options":[{"key":"A","text":"中断控制方式"},{"key":"B","text":"程序控制方式"},{"key":"C","text":"DMA控制方式"},{"key":"D","text":"通道控制方式"}],"answer":"B","explain":"程序控制方式也称为PIO（Programmed I/O，程控I/O）方式，是指由用户进程直接控制处理器或内存和外围设备之间进行信息传送的方式。"},{"id":149,"chapter":"第七章设备管理","type":"single","stem":"DMA控制方式的优点不包括（ ）","ref":"DMA方式优点：1）操作均由硬件电路实现，传输速度快；2）处理器仅在初始化和结束时参与，对数据传送基本上不干预，可以减少大批量数据传输时处理器的开销；3）处理器与外设并行工作，效率高","explanation":"DMA方式优点：1）操作均由硬件电路实现，传输速度快；2）处理器仅在初始化和结束时参与，对数据传送基本上不干预，可以减少大批量数据传输时处理器的开销；3）处理器与外设并行工作，效率高","options":[{"key":"A","text":"传输速度快"},{"key":"B","text":"减少大批量数据传输时处理器的开销"},{"key":"C","text":"处理器与外设并行工作，效率高"},{"key":"D","text":"释放内存空间"}],"answer":"D","explain":"DMA方式优点：1）操作均由硬件电路实现，传输速度快；2）处理器仅在初始化和结束时参与，对数据传送基本上不干预，可以减少大批量数据传输时处理器的开销；3）处理器与外设并行工作，效率高"},{"id":150,"chapter":"第七章设备管理","type":"single","stem":"为了提高设备分配的灵活性，用户申请设备时应使用（ ）","ref":"设备的指定方式：用户在申请独占设备时，指定需要什么设备，指定设备的方式可以有两种，一种是指定设备的绝对号，另一种是指定设备类、相对号","explanation":"设备的指定方式：用户在申请独占设备时，指定需要什么设备，指定设备的方式可以有两种，一种是指定设备的绝对号，另一种是指定设备类、相对号","options":[{"key":"A","text":"设备类、相对号"},{"key":"B","text":"设备类、绝对号"},{"key":"C","text":"设备的相对号"},{"key":"D","text":"设备的绝对号"}],"answer":"A","explain":"设备的指定方式：用户在申请独占设备时，指定需要什么设备，指定设备的方式可以有两种，一种是指定设备的绝对号，另一种是指定设备类、相对号"},{"id":151,"chapter":"第七章设备管理","type":"blank","stem":"______是直接内存访问（Direct Memory Access）的缩写，它是一种完全由硬件执行I/O数据交换的工作方式","ref":"DMA","explanation":"DMA","blankCount":1,"blanks":[["DMA"]],"explain":"考点2.5：**DMA**是直接内存访问（Direct Memory Access）的缩写，是一种完全由硬件执行I/O数据交换的工作方式——**DMA**控制器自动地控制成块数据在内存和I/O单元之间的传送。配套考点7.3：**DMA**控制方式的传送分三个阶段：传送前预处理、数据传送、传送后处理。"},{"id":152,"chapter":"第七章设备管理","type":"blank","stem":"______是一个特殊功能的处理器，它有自己的指令和程序，可以实现对外部设备的统一管理和外部设备与内存之间的数据传送","ref":"通道（channel）","explanation":"通道（channel）","blankCount":1,"blanks":[["通道（channel）","通道","channel"]],"explain":"考点2.5：**通道**是独立于处理器、专门负责数据I/O传输工作的处理单元，有自己的指令和程序（**通道**程序），可以实现对外部设备的统一管理和外部设备与内存之间的数据传送。配套考点7.3：**通道**的功能五条（接受CPU指令、执行**通道**程序、组织数据传输、收集保存状态信息、报告中断）。"},{"id":153,"chapter":"第七章设备管理","type":"essay","stem":"请回答通道有哪三种类型？简述三类通道的优缺点。","ref":"三种类型的通道：1）选择通道：优点：以数据块为单位进行传输，传输率高；缺点：通道利用率低。2）数组多路通道：优点：以数据块为单位进行传输，传输率高；又具有多路并行操作的能力，通道利用率高。缺点：控制复杂。3）字节多路通道：优点：多路并行操作能力与数组多路通道相同。缺点：以字节为单位交替进行的，各设备轮流占用一个很短的时间片，效率低","explanation":"三种类型的通道：1）选择通道：优点：以数据块为单位进行传输，传输率高；缺点：通道利用率低。2）数组多路通道：优点：以数据块为单位进行传输，传输率高；又具有多路并行操作的能力，通道利用率高。缺点：控制复杂。3）字节多路通道：优点：多路并行操作能力与数组多路通道相同。缺点：以字节为单位交替进行的，各设备轮流占用一个很短的时间片，效率低。","points":["选择通道：以数据块为单位进行传输，传输率高；通道利用率低","数组多路通道：传输率高，又具有多路并行操作的能力，利用率高；控制复杂","字节多路通道：多路并行；以字节为单位交替，轮流占用时间片，效率低"],"pointsMd":["选择通道：以数据块为单位进行传输，**传输率高**；通道**利用率低**","数组多路通道：传输率高，又具有**多路并行**操作的能力，利用率高；**控制复杂**","字节多路通道：多路并行；**以字节为单位**交替，轮流占用时间片，**效率低**"],"explain":"考点7.3 I/O设备的控制方式之通道控制方式：按照信息交换方式的不同，一个系统中可以设立三种类型的通道——①**选择通道**：以数据块为单位传输，**传输率高**，但一次只能连一台设备工作，通道利用率低；②**字节多路通道**：可连接多台低速设备并行工作，但以字节为单位传输、速率低；③**数组多路通道**：兼有两者优点——块传输速率高又具有多路并行操作能力、通道利用率高，缺点是**控制复杂**。"},{"id":154,"chapter":"第七章设备管理","type":"blank","stem":"I／0设备管理中，可按照两种方式进行设备分配，即______分配和______ 分配。","ref":"静态分配 、动态分配","explanation":"静态分配 、动态分配","blankCount":2,"blanks":[["静态分配"],["动态分配"]],"unordered":true,"explain":"考点7.4 设备的分配与回收：设备分配方式有两种，即**静态分配**（系统生成时一次分配好）和**动态分配**（进程运行中按需申请、用毕回收）。"},{"id":155,"chapter":"第七章设备管理","type":"blank","stem":"与进程调度相似，设备的分配策略通常采用的两种策略是：______ 和 ______。","ref":"先来先服务（FIFS）、高优先级优先","explanation":"先来先服务（FIFS）、高优先级优先","blankCount":2,"blanks":[["先来先服务（FIFS）","先来先服务","FIFS"],["高优先级优先"]],"unordered":true,"explain":"考点7.4：与进程调度相似，设备的分配策略通常采用两种：**先来先服务**（FCFS）和**高优先级优先**。"},{"id":156,"chapter":"第七章设备管理","type":"blank","stem":"操作系统设置“设备分配表”用来记录计算机系统所配置的独占设备类型、 台数以及分配情况等。 “设备分配表” 由 ______和______ 两部分组成。","ref":"设备类表 、 设备表","explanation":"设备类表 、 设备表","blankCount":2,"blanks":[["设备类表"],["设备表"]],"unordered":true,"explain":"考点7.4：操作系统设置“**设备分配表**”记录独占设备类型、台数及分配情况，由**设备类表**（每类设备概况）和**设备表**（每台设备状态）两部分组成。配套考点：分配算法实现常采用四张表——系统**设备表**、设备控制表、控制器控制表、通道控制表。"},{"id":157,"chapter":"第七章设备管理","type":"blank","stem":"由于独占设备的分配和回收必须遵守 “独占”的要求，设备利用率低，死锁几率增大，不利于调度，使用能将独占设备转变为共享设备的技术称为“______”系统可有效解决这个问题。","ref":"SPOOLing","explanation":"SPOOLing","blankCount":1,"blanks":[["SPOOLing"]],"explain":"考点7.7 虚拟设备技术：独占设备分配回收必须遵守“**独占**”要求，利用率低、死锁几率大；**SPOOLing**系统通过输入井/输出井和预输入预输出，把独占设备改造为逻辑上的共享设备，有效解决该问题。"},{"id":158,"chapter":"第七章设备管理","type":"essay","stem":"磁盘驱动调度包括什么调度?各涉及什么时间?","ref":"磁盘驱动调度包括移臂调度和旋转调度分别涉及寻找时间和延迟时间","explanation":"磁盘驱动调度包括移臂调度和旋转调度分别涉及寻找时间和延迟时间","points":["移臂调度和旋转调度，分别涉及寻找时间和延迟时间"],"pointsMd":["**移臂调度**和**旋转调度**，分别涉及**寻找时间**和**延迟时间**"],"explain":"考点7.5 磁盘驱动调度：磁盘驱动调度包括**移臂调度**和**旋转调度**两部分——**移臂调度**决定访问柱面（磁道）的次序，涉及寻找（寻道）时间；**旋转调度**决定同一柱面上访问扇区的次序，涉及**延迟时间**。配套：磁盘访问三时间=寻道时间+**延迟时间**+传送时间。"},{"id":159,"chapter":"第七章设备管理","type":"essay","stem":"简述关于磁盘的电梯调度算法与单向扫描调度算法的含义。","ref":"电梯调度算法是从移动臂当前位置开始沿移动方向去选择最近的柱面请求，当移臂方向上无请求时，就改变臂的移动方向再做类似处理。单向扫描调度算法总是从0号柱面开始向里扫面，为请求的柱面提供服务，到达最后一个柱面再把读写头快速返回0号柱面（返回过程中不做服务），返回后可再进行扫描和服务","explanation":"电梯调度算法是从移动臂当前位置开始沿移动方向去选择最近的柱面请求，当移臂方向上无请求时，就改变臂的移动方向再做类似处理。单向扫描调度算法总是从0号柱面开始向里扫面，为请求的柱面提供服务，到达最后一个柱面再把读写头快速返回0号柱面（返回过程中不做服务），返回后可再进行扫描和服务。","points":["电梯调度：从移动臂当前位置开始，沿移动方向去选择最近的柱面请求；无请求时改变臂的移动方向再做处理","单向扫描：从0号柱面开始，为请求的柱面提供服务，到达最后一个柱面，快速返回0号柱面、不做服务"],"pointsMd":["电梯调度：从移动臂当前位置开始，**沿移动方向**去选择最近的柱面请求；无请求时**改变臂的移动方向**再做处理","单向扫描：**从0号柱面开始**，为请求的柱面提供服务，到达最后一个柱面，**快速返回**0号柱面、不做服务"],"explain":"考点7.5 移臂调度算法：电梯调度算法——从移动臂当前位置开始沿移动方向去选择最近的柱面请求，当移臂方向上无请求时，就改变臂的移动方向再做类似处理（像电梯一样**顺路服务**、**到端换向**）。单向扫描调度算法——总是**从0号柱面开始**向里扫描，为有请求的柱面提供服务，到达最后一个柱面再把读写头**快速返回**0号柱面重新扫描（单向服务，返回空程）。"},{"id":160,"chapter":"第七章设备管理","type":"essay","stem":"常用的磁盘移臂驱动调度算法有哪些?","ref":"先来先服务调度算法、最短寻找时间优先调度算法、电梯调度算法、单向扫描调度算法","explanation":"先来先服务调度算法、最短寻找时间优先调度算法、电梯调度算法、单向扫描调度算法。","points":["先来先服务调度算法","最短寻找时间优先调度算法","电梯调度算法","单向扫描调度算法"],"pointsMd":["**先来先服务调度算法**","**最短寻找时间优先调度算法**","**电梯调度算法**","**单向扫描调度算法**"],"explain":"考点7.5：常用的移臂调度算法有四种——**先来先服务调度算法**、**最短寻道时间优先调度算法**、**电梯调度算法**和**单向扫描调度算法**。记忆顺序：公平→贪快→电梯→单向。"},{"id":161,"chapter":"第七章设备管理","type":"essay","stem":"简述磁盘驱动调度和调度原理。","ref":"磁盘执行一次输入输出所需时间是：寻找时间、延迟时间和传送时间；采用一定的调度策略以决定各等待访问者的执行次序，称为驱动调度；磁盘驱动调度就需要优化寻找时间和延迟时间，就是移臂调度和旋转调度","explanation":"磁盘执行一次输入输出所需时间是：寻找时间、延迟时间和传送时间；采用一定的调度策略以决定各等待访问者的执行次序，称为驱动调度；磁盘驱动调度就需要优化寻找时间和延迟时间，就是移臂调度和旋转调度。","points":["磁盘执行一次输入输出所需时间：寻找时间、延迟时间和传送时间","采用一定的调度策略，决定各等待访问者的执行次序，称为驱动调度","优化寻找时间和延迟时间，即移臂调度和旋转调度"],"pointsMd":["磁盘执行一次输入输出所需时间：**寻找时间**、**延迟时间**和**传送时间**","采用一定的调度策略，决定各等待访问者的执行次序，称为**驱动调度**","优化寻找时间和延迟时间，即**移臂调度**和**旋转调度**"],"explain":"考点7.5 磁盘驱动调度：磁盘执行一次输入输出所需时间=**寻找时间**（磁头在磁臂带动下移动到指定柱面所花的时间）+**延迟时间**（需要访问的扇区旋转到磁头下所需的时间）+**传送时间**（磁头读写完成信息传送的时间）。采用一定的调度策略以决定各等待访问者的执行次序，称为**驱动调度**；磁盘**驱动调度**就是优化**寻找时间**和**延迟时间**，即**移臂调度**和**旋转调度**。"},{"id":162,"chapter":"第七章设备管理","type":"single","stem":"把多个缓冲区连接起来统一管理的是（ ）","ref":"缓冲池则是把多个缓冲区连接起来统一管理，在缓冲池中的每个缓冲区既可用于输入又可用于输出的一种缓冲结构","explanation":"缓冲池则是把多个缓冲区连接起来统一管理，在缓冲池中的每个缓冲区既可用于输入又可用于输出的一种缓冲结构。","options":[{"key":"A","text":"单缓冲"},{"key":"B","text":"多缓冲"},{"key":"C","text":"缓冲池"},{"key":"D","text":"双缓冲"}],"answer":"C","explain":"缓冲池则是把多个缓冲区连接起来统一管理，在缓冲池中的每个缓冲区既可用于输入又可用于输出的一种缓冲结构。"},{"id":163,"chapter":"第七章设备管理","type":"single","stem":"为了缓解I／O设备与CPU速度的不匹配问题，可以引入（ ）","ref":"为了匹配I/O设备与CPU之间的处理速度，减少外部中断的次数和CPU进行中断处理所花费时间，并且解决DMA或通道方式中可能出现的瓶颈问题，通常都需要在设备管理中引入用来暂存数据的缓冲技术","explanation":"为了匹配I/O设备与CPU之间的处理速度，减少外部中断的次数和CPU进行中断处理所花费时间，并且解决DMA或通道方式中可能出现的瓶颈问题，通常都需要在设备管理中引入用来暂存数据的缓冲技术","options":[{"key":"A","text":"缓冲技术"},{"key":"B","text":"中断技术"},{"key":"C","text":"通道技术"},{"key":"D","text":"DMA技术"}],"answer":"A","explain":"为了匹配I/O设备与CPU之间的处理速度，减少外部中断的次数和CPU进行中断处理所花费时间，并且解决DMA或通道方式中可能出现的瓶颈问题，通常都需要在设备管理中引入用来暂存数据的缓冲技术"},{"id":164,"chapter":"第七章设备管理","type":"single","stem":"以下技术中，不能用于实现两台I/O设备之间的并行操作的是（ ）","ref":"单缓冲：在I/O设备和处理机之间设置一个缓冲区，但是I/O设备和I/O设备之间仍不能通过单缓冲实现并行操作","explanation":"单缓冲：在I/O设备和处理机之间设置一个缓冲区，但是I/O设备和I/O设备之间仍不能通过单缓冲实现并行操作","options":[{"key":"A","text":"单缓冲"},{"key":"B","text":"双缓冲"},{"key":"C","text":"多缓冲"},{"key":"D","text":"缓冲池"}],"answer":"A","explain":"单缓冲：在I/O设备和处理机之间设置一个缓冲区，但是I/O设备和I/O设备之间仍不能通过单缓冲实现并行操作"},{"id":165,"chapter":"第七章设备管理","type":"blank","stem":"______是指具有多个缓冲区，其中一部分缓冲区专门用于输入，另一部分缓冲区专门用于输出的缓冲结构。","ref":"多缓冲","explanation":"多缓冲","blankCount":1,"blanks":[["多缓冲"]],"explain":"考点7.6 缓冲技术：根据系统设置的缓冲区的个数，可把缓冲技术分为单缓冲、双缓冲、**多缓冲**以及缓冲池。**多缓冲**是指具有多个缓冲区，一部分专门用于输入、另一部分专门用于输出，使输入输出并行。"},{"id":166,"chapter":"第七章设备管理","type":"blank","stem":"对于各缓冲区的排列以及每次取出和插入缓冲队列的顺序都应有一定的规则最简单的方法是______","ref":"FIFO(先进先出)","explanation":"FIFO(先进先出)","blankCount":1,"blanks":[["FIFO(先进先出)","FIFO","先进先出"]],"explain":"考点7.6：对各缓冲区的排列以及每次取出和插入缓冲队列的顺序都应有规则，最简单的方法是**FIFO**（先进先出）。配套考点：缓冲池中四种工作缓冲区——收容输入hin、提取输入sin、收容输出hout、提取输出sout。"},{"id":167,"chapter":"第七章设备管理","type":"blank","stem":"在SPOOLing系统中，作业执行时，从磁盘上的______中读取数据，并把作业的执行结果暂时存放在磁盘上的______中。","ref":"输入井 、输出井","explanation":"输入井 、输出井","blankCount":2,"blanks":[["输入井"],["输出井"]],"explain":"考点7.7：SPOOLing系统在磁盘上设置**输入井**和**输出井**——作业执行时从**输入井**读取（预输入好的）数据，执行结果暂时存放在**输出井**，再由慢速设备慢慢输出。"},{"id":168,"chapter":"第七章设备管理","type":"blank","stem":"______是多道程序设计系统中处理独占外部设备的一种方法可以提高设备利用率并缩短单个程序的响应时间。","ref":"虚拟设备技术或SPOOLing技术","explanation":"虚拟设备技术或SPOOLing技术","blankCount":1,"blanks":[["虚拟设备技术或SPOOLing技术","虚拟设备技术","SPOOLing技术"]],"explain":"考点7.7：虚拟设备技术，又称为**SPOOLing**技术，是多道程序设计系统中处理独占外部设备的一种方法，它可以提高设备利用率并缩短单个程序的响应时间。"},{"id":169,"chapter":"第七章设备管理","type":"blank","stem":"SPOOLing系统主要包括______、 ______、 ______三部分","ref":"输入程序模块、输出程序模块、作业调度程序","explanation":"输入程序模块、输出程序模块、作业调度程序","blankCount":3,"blanks":[["输入程序模块"],["输出程序模块"],["作业调度程序"]],"unordered":true,"explain":"考点7.7：SPOOLing系统主要包括**输入程序模块**（预输入）、**输出程序模块**（预输出）、**作业调度程序**三部分。"},{"id":170,"chapter":"第七章设备管理","type":"essay","stem":"什么是SPOOLing技术？SPOOLing技术的主要作用是什么？","ref":"虚拟设备技术，又称为SPOOLing技术，是多道程序设计系统中处理独占I/O设备的一种方法，它的作用是可以提高设备利用率并缩短单个程序的响应时间","explanation":"虚拟设备技术，又称为SPOOLing技术，是多道程序设计系统中处理独占I/O设备的一种方法，它的作用是可以提高设备利用率并缩短单个程序的响应时间。","points":["虚拟设备技术，又称为SPOOLing技术","多道程序设计系统中处理独占I/O设备的一种方法","作用：提高设备利用率，缩短单个程序的响应时间"],"pointsMd":["虚拟设备技术，又称为**SPOOLing**技术","多道程序设计系统中处理**独占**I/O设备的一种方法","作用：提高设备**利用率**，缩短单个程序的**响应时间**"],"explain":"考点7.7 虚拟设备技术：虚拟设备技术又称为**SPOOLing**技术，是多道程序设计系统中处理独占外部设备的一种方法——用磁盘上的**输入井**/**输出井**和预输入、预输出程序把独占设备改造成逻辑上的**共享设备**。主要作用：可以提高设备利用率并缩短单个程序的响应时间。"},{"id":171,"chapter":"第八章进程同步机制与死锁","type":"single","stem":"以下关于进程的叙述中，不正确的是（ ）","ref":"有关的并发进程才有共享的变量。无关的并发进程没有共享变量，这些并发进程分别在各自的数据集合上操作","explanation":"有关的并发进程才有共享的变量。无关的并发进程没有共享变量，这些并发进程分别在各自的数据集合上操作。","options":[{"key":"A","text":"在逻辑上具有某种联系的进程称为相关进程"},{"key":"B","text":"在逻辑上没有任何联系的进程称为无关进程"},{"key":"C","text":"无关的并发进程有共享的变量"},{"key":"D","text":"一个进程的执行依赖其他进程的进展情况，则这些并发进程是相关的"}],"answer":"C","explain":"有关的并发进程才有共享的变量。无关的并发进程没有共享变量，这些并发进程分别在各自的数据集合上操作。"},{"id":172,"chapter":"第八章进程同步机制与死锁","type":"single","stem":"进程之间一种直接的协同工作关系，一些进程相互合作，共同完成一项任务是指（ ）","ref":"进程同步概念","explanation":"进程同步概念。","options":[{"key":"A","text":"进程的互斥"},{"key":"B","text":"进程的同步"},{"key":"C","text":"进程的相容"},{"key":"D","text":"进程的异步"}],"answer":"B","explain":"进程同步概念。"},{"id":173,"chapter":"第八章进程同步机制与死锁","type":"single","stem":"在系统中，许多进程常常需要共享资源，而这些资源往往要求排他性的使用，即一次只能为一个进程服务，因此，各进程间只能互斥使用这些资源，进程间的这种关系被称为（ ）","ref":"进程的互斥概念","explanation":"进程的互斥概念。","options":[{"key":"A","text":"进程的互斥"},{"key":"B","text":"进程的相容"},{"key":"C","text":"进程的同步"},{"key":"D","text":"进程的异步"}],"answer":"A","explain":"进程的互斥概念。"},{"id":174,"chapter":"第八章进程同步机制与死锁","type":"single","stem":"对信号量S实施V操作之后（ ）","ref":"V操作。若S<0，将该进程状态置为等待状态；若 S≤0，释放在S信号量队列中等待的一个进程，将其状态改变为就绪态","explanation":"V操作。若S<0，将该进程状态置为等待状态；若 S≤0，释放在S信号量队列中等待的一个进程，将其状态改变为就绪态。","options":[{"key":"A","text":"当S<0时要释放一个等待进程，将其改为就绪态"},{"key":"B","text":"当S<0时要释放一个运行进程，将其改为就绪态"},{"key":"C","text":"当S≤0时要释放一个等待进程，将其改为就绪态"},{"key":"D","text":"当S≤0时要释放一个运行进程，将其改为就绪态"}],"answer":"C","explain":"V操作。若S<0，将该进程状态置为等待状态；若 S≤0，释放在S信号量队列中等待的一个进程，将其状态改变为就绪态。"},{"id":175,"chapter":"第八章进程同步机制与死锁","type":"single","stem":"用信号量S来管理一组临界资源，S初值为4，若多次 P、 V操作后，S当前值为-1，则表示当前正在使用这些临界资源的进程共有（ ）","ref":"P、V操作的物理含义。当S<0时，表示没有可分配的资源数量，其S的绝对值表示排在S信号量的等待队列中进程的数目。 S当前值为-1，表示4个资源都被分配出去了，有4个进程在临界区","explanation":"P、V操作的物理含义。当S<0时，表示没有可分配的资源数量，其S的绝对值表示排在S信号量的等待队列中进程的数目。 S当前值为-1，表示4个资源都被分配出去了，有4个进程在临界区。","options":[{"key":"A","text":"5个"},{"key":"B","text":"4个"},{"key":"C","text":"3个"},{"key":"D","text":"2个"}],"answer":"B","explain":"P、V操作的物理含义。当S<0时，表示没有可分配的资源数量，其S的绝对值表示排在S信号量的等待队列中进程的数目。 S当前值为-1，表示4个资源都被分配出去了，有4个进程在临界区。"},{"id":176,"chapter":"第八章进程同步机制与死锁","type":"blank","stem":"在并发程序中共享了公共变量，使得程序的计算结果与并发程序执行的速度有关。这种情况引起的错误称为______。","ref":"与时间有关的错误","explanation":"与时间有关的错误","blankCount":1,"blanks":[["与时间有关的错误"]],"explain":"考点8.1 进程的同步与互斥：临界资源是需要**互斥使用**的硬件或软件资源（外设、共享代码段、共享数据结构等）。并发程序共享公共变量使计算结果与执行速度有关，这种错误称为**与时间有关的错误**，须用互斥机制解决。"},{"id":177,"chapter":"第八章进程同步机制与死锁","type":"blank","stem":"多道程序系统中并发进程通常有多个。在逻辑上具有某种联系的进程称为______","ref":"相关进程","explanation":"相关进程","blankCount":1,"blanks":[["相关进程"]],"explain":"考点8.1：多道程序系统中并发进程通常有多个，在逻辑上具有某种联系（合作或竞争）的进程称为**相关进程**，无逻辑联系的为独立进程。"},{"id":178,"chapter":"第八章进程同步机制与死锁","type":"blank","stem":"Dijkstra把同步问题抽象成一种“______”","ref":"生产者-消费者关系","explanation":"生产者-消费者关系","blankCount":1,"blanks":[["生产者-消费者关系"]],"explain":"考点8.2 经典的进程同步问题：简单**生产者—消费者**问题、多个**生产者—消费者**问题、**读者—写者**问题。Dijkstra把同步问题抽象成一种“**生产者—消费者关系**”：一方投放产品、另一方提取产品，互相制约。"},{"id":179,"chapter":"第八章进程同步机制与死锁","type":"blank","stem":"互斥时对信号量的PV操作通常在______中，而同步的PV操作分布在______中。","ref":"同一进程,不同进程","explanation":"同一进程,不同进程","blankCount":2,"blanks":[["同一进程"],["不同进程"]],"explain":"考点8.1 信号量机制：利用操作系统提供的**信号量机制**可实现临界资源的互斥访问。互斥的PV操作通常在**同一进程**中成对出现（进入/退出临界区）；同步的PV操作分布在不同（相关）进程中（**一个释放、一个等待**）。"},{"id":180,"chapter":"第八章进程同步机制与死锁","type":"blank","stem":"对信号量的PV操作在程序流程上必定是成对出现，不能缺少，缺少了会______","ref":"死锁","explanation":"死锁","blankCount":1,"blanks":[["死锁"]],"explain":"考点8.1：对信号量的PV操作在程序流程上必定成对出现、不能缺少：只有P没有V，资源得不到释放，进程互相等待，缺少了会**死锁**。"},{"id":181,"chapter":"第八章进程同步机制与死锁","type":"single","stem":"资源的有序分配法破坏了死锁必要条件的（ ）","ref":"采用资源有序分配策略打破了循环等待的条件","explanation":"采用资源有序分配策略打破了循环等待的条件。","options":[{"key":"A","text":"互斥条件"},{"key":"B","text":"请求和保持条件"},{"key":"C","text":"不可剥夺条件"},{"key":"D","text":"循环等待条件"}],"answer":"D","explain":"采用资源有序分配策略打破了循环等待的条件。"},{"id":182,"chapter":"第八章进程同步机制与死锁","type":"single","stem":"资源静态分配方法可以预防死锁，如果进程在执行前就申请它所需的全部资源，仅当系统能满足要求且一次性分配资源后，该进程才能执行。这样的资源静态分配策略破坏了死锁四个必要条件中的（ ）","ref":"每个进程必须在开始执行前就申请它所需要的全部资源，仅当系统能满足进程的资源申请要求且把资源一次性分配给进程后，该进程才能开始执行， 采用该方法后，进程在执行过程中不再申请资源，故不可能出现占有了某些资源再等待其他资源的情况，即“请求和保持”的条件不成立，从而预防死锁的发生","explanation":"每个进程必须在开始执行前就申请它所需要的全部资源，仅当系统能满足进程的资源申请要求且把资源一次性分配给进程后，该进程才能开始执行， 采用该方法后，进程在执行过程中不再申请资源，故不可能出现占有了某些资源再等待其他资源的情况，即“请求和保持”的条件不成立，从而预防死锁的发生。","options":[{"key":"A","text":"互斥条件"},{"key":"B","text":"请求和保持条件"},{"key":"C","text":"不可划夺条件"},{"key":"D","text":"循环等待条件"}],"answer":"B","explain":"每个进程必须在开始执行前就申请它所需要的全部资源，仅当系统能满足进程的资源申请要求且把资源一次性分配给进程后，该进程才能开始执行， 采用该方法后，进程在执行过程中不再申请资源，故不可能出现占有了某些资源再等待其他资源的情况，即“请求和保持”的条件不成立，从而预防死锁的发生。"},{"id":183,"chapter":"第八章进程同步机制与死锁","type":"single","stem":"设有两个进程共享5个同类资源，为使系统不会死锁，每个进程可以申请的该类资源数目最多为（ ）","ref":"每个进程都已分配到2个资源，系统还剩下一个资源， 就能保证某一个进程能分配到全部3个资源，并能运行到底，最终释放这3个资源。因此每个进程最多可以申请3个资源","explanation":"每个进程都已分配到2个资源，系统还剩下一个资源， 就能保证某一个进程能分配到全部3个资源，并能运行到底，最终释放这3个资源。因此每个进程最多可以申请3个资源。","options":[{"key":"A","text":"1个"},{"key":"B","text":"2个"},{"key":"C","text":"3个"},{"key":"D","text":"4个"}],"answer":"C","explain":"每个进程都已分配到2个资源，系统还剩下一个资源， 就能保证某一个进程能分配到全部3个资源，并能运行到底，最终释放这3个资源。因此每个进程最多可以申请3个资源。"},{"id":184,"chapter":"第八章进程同步机制与死锁","type":"single","stem":"下列哪一项对实时系统和长时间运行的数据处理来说是一种常用技术（ ）","ref":"剥夺资源经常使用的方法如下。1）还原算法，即恢复计算结果和状态。2）建立检查点主要是用来恢复分配前的状态。（对实时系统和长时间运行的数据处理是一种常用技术）","explanation":"剥夺资源经常使用的方法如下。1）还原算法，即恢复计算结果和状态。2）建立检查点主要是用来恢复分配前的状态。（对实时系统和长时间运行的数据处理是一种常用技术）","options":[{"key":"A","text":"还原算法"},{"key":"B","text":"建立检查点"},{"key":"C","text":"撤销进程"},{"key":"D","text":"死锁预防"}],"answer":"B","explain":"剥夺资源经常使用的方法如下。1）还原算法，即恢复计算结果和状态。2）建立检查点主要是用来恢复分配前的状态。（对实时系统和长时间运行的数据处理是一种常用技术）"},{"id":185,"chapter":"第八章进程同步机制与死锁","type":"blank","stem":"处于死锁状态的进程称为______ 。","ref":"死锁进程","explanation":"死锁进程","blankCount":1,"blanks":[["死锁进程"]],"explain":"考点8.3 死锁：系统发生死锁现象称为系统处于死锁状态，处于死锁状态的进程称为**死锁进程**。"},{"id":186,"chapter":"第八章进程同步机制与死锁","type":"blank","stem":"系统发生死锁时，死锁进程的个数至少为两个。 所有死锁进程都在等待资源，并且其中至少有______进程已占有资源。","ref":"两个","explanation":"两个","blankCount":1,"blanks":[["两个"]],"explain":"考点8.3：死锁定义——一组进程中的每一个进程均无限期地等待被该组进程中的另一个进程所占有且永远不会释放的资源。因此死锁进程至少**两个**，且其中至少**两个**进程已占有资源又在等待别人的资源，形成闭环。"},{"id":187,"chapter":"第八章进程同步机制与死锁","type":"blank","stem":"死锁产生的必要条件：互斥条件、 不可剥夺条件、 ______、 ______ 。","ref":"请求和保持条件 、循环等待条件","explanation":"请求和保持条件 、循环等待条件","blankCount":2,"blanks":[["请求和保持条件"],["循环等待条件"]],"unordered":true,"explain":"考点8.3：死锁产生的必要条件四条——（1）互斥条件；（2）不可剥夺条件；（3）**请求和保持条件**；（4）**循环等待条件**。死锁预防就是设置严格限制、**破坏**其中任一必要条件（防患于未然）。"},{"id":188,"chapter":"第八章进程同步机制与死锁","type":"essay","stem":"什么是死锁？产生死锁的两个主要原因？","ref":"所谓死锁是指在多道程序系统中的一种现象，一组进程中的每个进程均无限期地等待被该组进程中的另一个进程所占有且永远不会释放的资源。产生死锁的原因主要有两个：1）竞争资源，系统资源在分配时出现失误，进程间对资源的相互争夺而造成僵局；2）多道程序运行时，进程推进顺序不合理","explanation":"所谓死锁是指在多道程序系统中的一种现象，一组进程中的每个进程均无限期地等待被该组进程中的另一个进程所占有且永远不会释放的资源。产生死锁的原因主要有两个：1）竞争资源，系统资源在分配时出现失误，进程间对资源的相互争夺而造成僵局；2）多道程序运行时，进程推进顺序不合理","points":["死锁：一组进程均无限期地等待被该组进程中另一个进程占有且永远不会释放的资源","竞争资源，分配时出现失误，相互争夺、造成僵局","多道程序运行时进程推进顺序不合理"],"pointsMd":["死锁：一组进程均**无限期**地等待被该组进程中另一个进程占有且**永远不会释放**的资源","**竞争资源**，分配时出现失误，相互争夺、造成**僵局**","多道程序运行时进程**推进顺序**不合理"],"explain":"考点8.3 死锁：所谓死锁，是指在多道程序系统中的一种现象，一组进程中的每一个进程均**无限期**地等待被该组进程中的另一个进程所占有且永远不会释放的资源。产生死锁的原因主要有两个：（1）**竞争资源**——系统资源在分配时出现失误，进程间对资源的相互争夺而造成僵局；（2）多道程序运行时，进程**推进顺序**不合理。配套考点：四个必要条件（互斥、不可剥夺、请求和保持、循环等待）与解除方法（剥夺资源、撤销进程）。"},{"id":189,"chapter":"第八章进程同步机制与死锁","type":"blank","stem":"______是操作系统中关于进程同步与互斥的经典问题，也是涉及到______的关键问题。","ref":"哲学家就餐问题,死锁","explanation":"哲学家就餐问题,死锁","blankCount":2,"blanks":[["哲学家就餐问题"],["死锁"]],"explain":"考点8.4：**哲学家就餐问题**是操作系统中关于进程同步与互斥的经典问题，也是涉及**死锁**的关键问题——若每个哲学家都先拿起左筷再等待右筷，就会互相循环等待而**死锁**。"},{"id":190,"chapter":"第八章进程同步机制与死锁","type":"blank","stem":"在哲学家就餐问题中为每只筷子设置一个信号量，一个哲学家通过在相应信号量上执行操作______抓起一只筷子，通过执行______操作放下一只筷子","ref":"P，V","explanation":"P，V","blankCount":2,"blanks":[["P"],["V"]],"explain":"考点8.4：为每只筷子设置一个信号量，一个哲学家通过在相应信号量上执行**P操作**抓起一只筷子（申请资源），通过执行**V操作**放下一只筷子（释放资源）。"}]};
